MAXPARTICIPANTS = 32
MINPARTICIPANTS = 2

ID_RE = re.compile(r'[A-Za-z0-9_.-]{1,32}\Z')


class Invalid(Exception):
    """Raised when a command fails JSON/schema validation."""


def _int(x):
    if type(x) is not int:
        raise Invalid
    return x


def _bool(x):
    if type(x) is not bool:
        raise Invalid
    return x


def _id(x):
    if not isinstance(x, str):
        raise Invalid
    if ID_RE.match(x) is None:
        raise Invalid
    return x


def _tick(x):
    v = _int(x)
    if v < 0 or v > MAXT:
        raise Invalid
    return v


def _rev(x):
    v = _int(x)
    if v < 0 or v > MAXREV:
        raise Invalid
    return v


def _amount(x):
