static int rank_from_ordinal_excluding(int excluded_rank, int ordinal) {
    for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
        if (r == excluded_rank) {
            continue;
        }
        if (ordinal == 0) {
            return r;
        }
        ordinal--;
    }
    return 0;
}

static int ordinal_excluding(int excluded_rank, int rank) {
    int ordinal = 0;
    for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
        if (r == excluded_rank) {
            continue;
        }
        if (r == rank) {
            return ordinal;
        }
        ordinal++;
    }
    return 0;
}

