def _closest_cut(job):
    """Fallback witness set when construction could not finish."""
    C = job.C
    best = None
    bestval = None
    for k in range(1, len(C)):
        S = C[:k]
        cap, dem = compiler.cut_value(job, S)
        val = cap - dem
        if bestval is None or val < bestval:
            bestval = val
            best = S
    if best is None:
        best = [C[0]]
    return sorted(best)
