"""Reference output builder + random document generator for cross-checking."""
import json
import random
import string
import subprocess
import sys

sys.path.insert(0, '/workspace/tmp/ref')
from replay import simulate
from http import parse

MOD = 1 << 64


def fp(data):
    h = 0
    for c in data:
        h = (h * 257 + c + 1) % MOD
    return {'n': len(data), 'h': '%016x' % h}


def action_bytes(at, stream, kind, data, end):
    out = at.to_bytes(8, 'big') + stream.to_bytes(4, 'big') + kind.encode('ascii')
    if kind in ('H', 'h'):
        out += len(data).to_bytes(8, 'big')
        for n, v in data:
            out += len(n).to_bytes(8, 'big') + n
            out += len(v).to_bytes(8, 'big') + v
    else:
        out += len(data).to_bytes(8, 'big') + data
    return out + bytes((1 if end else 0,))


def field_fp(fields):
    out = bytearray()
    out += len(fields).to_bytes(8, 'big')
    for n, v in fields:
        out += len(n).to_bytes(8, 'big') + n
        out += len(v).to_bytes(8, 'big') + v
    return fp(bytes(out))


