def pybytes(data):
    out = ['b"']
    for byte in data:
        ch = chr(byte)
        if ch in '"\\':
            out.append('\\' + ch)
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\t':
            out.append('\\t')
        elif 0x20 <= byte <= 0x7e:
            out.append(ch)
        else:
            out.append('\\x%02x' % byte)
    out.append('"')
    return ''.join(out)


def token(seed, coord, occ):
    return hashlib.sha256(('%s/%s/%d' % (seed, coord, occ)).encode()).hexdigest()[:20].encode()


def resolve(data, seed, coord):
    if data.startswith('{{') and data.endswith('}}'):
