    0x90befffau, 0xa4506cebu, 0xbef9a3f7u, 0xc67178f2u
};

#define ROR32(x, n) (((x) >> (n)) | ((x) << (32 - (n))))

static void sha_block(uint32_t st[8], const uint8_t blk[64]) {
    uint32_t w[64];
    for (int i = 0; i < 16; i++) {
        w[i] = ((uint32_t)blk[4 * i] << 24) | ((uint32_t)blk[4 * i + 1] << 16) |
               ((uint32_t)blk[4 * i + 2] << 8) | (uint32_t)blk[4 * i + 3];
    }
    for (int i = 16; i < 64; i++) {
        uint32_t s0 = ROR32(w[i - 15], 7) ^ ROR32(w[i - 15], 18) ^ (w[i - 15] >> 3);
        uint32_t s1 = ROR32(w[i - 2], 17) ^ ROR32(w[i - 2], 19) ^ (w[i - 2] >> 10);
        w[i] = w[i - 16] + s0 + w[i - 7] + s1;
    }
    uint32_t a = st[0], b = st[1], c = st[2], d = st[3];
    uint32_t e = st[4], f = st[5], g = st[6], h = st[7];
    for (int i = 0; i < 64; i++) {
        uint32_t S1 = ROR32(e, 6) ^ ROR32(e, 11) ^ ROR32(e, 25);
        uint32_t ch = (e & f) ^ ((~e) & g);
        uint32_t t1 = h + S1 + ch + sha_k[i] + w[i];
        uint32_t S0 = ROR32(a, 2) ^ ROR32(a, 13) ^ ROR32(a, 22);
        uint32_t mj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = S0 + mj;
        h = g; g = f; f = e; e = d + t1;
        d = c; c = b; b = a; a = t1 + t2;
    }
    st[0] += a; st[1] += b; st[2] += c; st[3] += d;
    st[4] += e; st[5] += f; st[6] += g; st[7] += h;
}

static void sha_init(sha_t *s) {
    static const uint32_t iv[8] = { 0x6a09e667u, 0xbb67ae85u, 0x3c6ef372u,
                                    0xa54ff53au, 0x510e527fu, 0x9b05688cu,
                                    0x1f83d9abu, 0x5be0cd19u };
    memcpy(s->st, iv, sizeof iv);
    s->bits = 0;
    s->buflen = 0;
}

static void sha_update(sha_t *s, const void *data, size_t len) {
    const uint8_t *p = data;
    s->bits += (uint64_t)len * 8u;
    if (s->buflen) {
        size_t need = 64 - s->buflen;
        if (len < need) {
            memcpy(s->buf + s->buflen, p, len);
            s->buflen += len;
            return;
        }
        memcpy(s->buf + s->buflen, p, need);
        sha_block(s->st, s->buf);
        p += need;
        len -= need;
        s->buflen = 0;
    }
    while (len >= 64) {
        sha_block(s->st, p);
        p += 64;
        len -= 64;
    }
    if (len) {
        memcpy(s->buf, p, len);
        s->buflen = len;
    }
}

static void sha_finish(const sha_t *src, uint8_t out[32]) {
    sha_t s = *src;
    uint64_t bits = s.bits;
    uint8_t pad = 0x80;
    sha_update(&s, &pad, 1);
    pad = 0;
    while (s.buflen != 56) {
        sha_update(&s, &pad, 1);
    }
    uint8_t tail[8];
    for (int i = 0; i < 8; i++) {
        tail[i] = (uint8_t)(bits >> (56 - 8 * i));
    }
    sha_update(&s, tail, 8);
    for (int i = 0; i < 8; i++) {
        out[4 * i] = (uint8_t)(s.st[i] >> 24);
        out[4 * i + 1] = (uint8_t)(s.st[i] >> 16);
        out[4 * i + 2] = (uint8_t)(s.st[i] >> 8);
        out[4 * i + 3] = (uint8_t)s.st[i];
    }
}

