    """Expand a recipe into the list of (link, direction) traversals."""
    if memo is None:
        memo = {}
    stack = [node_id]
    out = []
    while stack:
        nid = stack.pop()
        if nid in memo:
            out.extend(memo[nid])
            continue
        node = recipes[nid]
        if node[0] == 0:
            memo[nid] = [(node[1], node[2])]
            out.append((node[1], node[2]))
        else:
            left = _expand(recipes, node[1], links, memo)
            right = _expand(recipes, node[2], links, memo)
            memo[nid] = left + right
            out.extend(left)
            out.extend(right)
    return out


