    // ------------------------------------------------------------------ events

    private void datagram(int ev, Main.Event e) {
        byte[] wire = e.wire;
        List<Long> auth = e.auth;
        dgBuffer = new ByteArrayOutputStream();
        dgAccepted = 0;
        dgPackets = 0;
        int pos = 0;
        int attempt = 0;
        while (pos < wire.length) {
            int start = pos;
            Env env = header(wire, start);
            if (env == null) {
                packetRows.add(Main.object("event", (long) ev, "packet", (long) attempt, "offset",
                        (long) start, "level", null, "pn", null, "epoch", null, "status", BAD_HEADER,
                        "sha256", null));
                dgPackets = attempt + 1;
                break;
            }
            dgPackets = attempt + 1;
            Long ann = (auth != null && attempt < auth.size()) ? auth.get(attempt) : null;
            packet(ev, attempt, start, env, ann);
            attempt++;
            pos = env.end;
            if (env.level == 2) {
                break;
            }
        }
        byte[] accepted = dgBuffer.toByteArray();
        datagramRows.add(Main.object("event", (long) ev, "packets", (long) dgPackets, "accepted",
                (long) dgAccepted, "bytes", (long) accepted.length, "sha256", sha256(accepted, 0, accepted.length)));
    }

    // ------------------------------------------------------------------ headers

    private Env header(byte[] w, int pos) {
        int b0 = w[pos] & 255;
        Env env = new Env();
        if ((b0 & 0x80) != 0) {
            if (b0 >= 0xc0 && b0 <= 0xc3) {
                env.level = 0;
            } else if (b0 >= 0xe0 && b0 <= 0xe3) {
                env.level = 1;
            } else {
                return null;
            }
            int pnWidth = (b0 & 3) + 1;
            int p = pos + 1;
            if (w.length - p < 4) {
                return null;
            }
            if (w[p] != 0 || w[p + 1] != 0 || w[p + 2] != 0 || w[p + 3] != 1) {
                return null;
            }
            p += 4;
            if (p >= w.length) {
                return null;
            }
            int dcidLen = w[p++] & 255;
            if (dcidLen > 20 || w.length - p < dcidLen) {
                return null;
            }
            env.dcid = Arrays.copyOfRange(w, p, p + dcidLen);
            p += dcidLen;
            if (p >= w.length) {
                return null;
            }
            int scidLen = w[p++] & 255;
            if (scidLen > 20 || w.length - p < scidLen) {
                return null;
            }
            env.scid = Arrays.copyOfRange(w, p, p + scidLen);
            p += scidLen;
            if (env.level == 0) {
                long[] v = varint(w, p);
                if (v == null) {
                    return null;
                }
                long tokenLen = v[0];
                p = (int) v[1];
                if (tokenLen > w.length - p) {
                    return null;
                }
                env.token = Arrays.copyOfRange(w, p, p + (int) tokenLen);
                p += (int) tokenLen;
            }
            long[] v = varint(w, p);
            if (v == null) {
                return null;
            }
            long length = v[0];
            p = (int) v[1];
            if (length < pnWidth || length > w.length - p) {
                return null;
            }
            if (w.length - p < pnWidth) {
                return null;
            }
            long raw = 0;
            for (int i = 0; i < pnWidth; i++) {
                raw = (raw << 8) | (w[p + i] & 255L);
            }
            p += pnWidth;
            int payloadLen = (int) (length - pnWidth);
            env.payload = Arrays.copyOfRange(w, p, p + payloadLen);
            p += payloadLen;
            env.pnWidth = pnWidth;
            env.rawPn = raw;
            env.end = p;
            env.phase = 0;
            return env;
        }
        if ((b0 & 0x40) == 0 || (b0 & 0x18) != 0) {
            return null;
        }
        env.level = 2;
        env.phase = (b0 >> 2) & 1;
        int pnWidth = (b0 & 3) + 1;
        int p = pos + 1;
        if (cidWidth == 0 || w.length - p < cidWidth) {
            return null;
        }
        env.dcid = Arrays.copyOfRange(w, p, p + cidWidth);
        p += cidWidth;
        if (w.length - p < pnWidth) {
            return null;
        }
        long raw = 0;
        for (int i = 0; i < pnWidth; i++) {
            raw = (raw << 8) | (w[p + i] & 255L);
        }
        p += pnWidth;
        env.payload = Arrays.copyOfRange(w, p, w.length);
        env.pnWidth = pnWidth;
        env.rawPn = raw;
        env.end = w.length;
        return env;
    }

    /** Returns {value, next position} or null when the varint is truncated. */
    private static long[] varint(byte[] w, int p) {
        if (p >= w.length) {
            return null;
        }
        int b = w[p] & 255;
        int width = 1 << (b >>> 6);
        if (width > w.length - p) {
            return null;
        }
        long v = b & 0x3fL;
        for (int i = 1; i < width; i++) {
            v = (v << 8) | (w[p + i] & 255L);
        }
        return new long[] {v, p + width};
    }

    /** Closest nonnegative integer congruent to raw modulo 2^(8*width); ties pick the larger. */
    static long reconstruct(long raw, int width, long expected) {
        long modulus = 1L << (8 * width);
        long delta = expected - raw;
        long k = Math.floorDiv(delta, modulus);
        if (k < 0) {
            k = 0;
        }
        long low = raw + k * modulus;
        long high = low + modulus;
        long dLow = Math.abs(expected - low);
        long dHigh = high - expected;
        return dHigh <= dLow ? high : low;
    }

    private long expected(int level) {
        return largest[level] < 0 ? 0 : largest[level] + 1;
    }

    private int route(byte[] dcid) {
        if (dcid.length != cidWidth) {
            return -1;
        }
        for (int i = 0; i < localCids.length; i++) {
            if (Arrays.equals(localCids[i], dcid)) {
                return retiredLocal.contains((long) i) ? -1 : i;
            }
        }
        return -1;
    }

    // ------------------------------------------------------------------ packets

    private void packet(int ev, int pkt, int offset, Env env, Long ann) {
        int level = env.level;
        long pn = reconstruct(env.rawPn, env.pnWidth, expected(level));
        if (closed) {
            emit(ev, pkt, offset, level, pn, null, CLOSED, null);
            return;
        }
        int dcidSeq = route(env.dcid);
        if (dcidSeq < 0) {
            emit(ev, pkt, offset, level, pn, null, DROP_CID, null);
            return;
        }
        if (!key[level]) {
            emit(ev, pkt, offset, level, pn, null, NO_KEY, null);
            return;
        }
        if (pn > MAX62) {
            emit(ev, pkt, offset, level, pn, null, PN_RANGE, null);
            return;
        }
        Long epoch = null;
        if (level != 2) {
            if (ann == null || ann != 0) {
                emit(ev, pkt, offset, level, pn, null, AUTH, null);
                return;
            }
        } else {
            if (ann == null) {
                emit(ev, pkt, offset, level, pn, null, AUTH, null);
                return;
            }
            long current = scal[S_EPOCH];
            boolean window = ann == current || (ann + 1 == current) || (ann == current + 1 && current + 1 <= MAX62);
            if (!window || (ann & 1L) != (env.phase & 1L)) {
                emit(ev, pkt, offset, level, pn, null, AUTH, null);
                return;
            }
            epoch = ann;
        }
        if (seen.get(level).contains(pn)) {
            emit(ev, pkt, offset, level, pn, epoch, DUPLICATE, null);
            return;
        }
        if (level == 2) {
            for (Map.Entry<Long, long[]> en : epochs.entrySet()) {
                long e = en.getKey();
                if (e == epoch) {
                    continue;
                }
                long[] st = en.getValue();
                if (epoch > e ? pn <= st[1] : pn >= st[0]) {
                    close(KEY_UPDATE_ERROR, 0, ev, pkt);
                    emit(ev, pkt, offset, level, pn, epoch, KEY_UPDATE_ERROR, null);
                    return;
                }
            }
        }
        frames.clear();
        long before = expected(level);
        boolean peerClose = false;
        long closeAt = 0;
        try {
            peerClose = frameAudit(env, dcidSeq);
            closeAt = closeOffsetOfFrame;
            accept(level, pn, epoch);
            journal.commit();
        } catch (WireException ex) {
            journal.rollback();
            close(ex.code, ex.offset, ev, pkt);
            emit(ev, pkt, offset, level, pn, epoch, ex.code, null);
            return;
        }
        if (peerClose) {
            close(PEER_CLOSE, closeAt, ev, pkt);
        }
        byte[] canonical = canonical(env, pn, before);
        dgBuffer.write(canonical, 0, canonical.length);
        dgAccepted++;
        emit(ev, pkt, offset, level, pn, epoch, peerClose ? PEER_CLOSE : OK, sha256(canonical, 0, canonical.length));
    }

    private long closeOffsetOfFrame;

    private void emit(int ev, int pkt, int offset, int level, long pn, Long epoch, String status, String hash) {
        packetRows.add(Main.object("event", (long) ev, "packet", (long) pkt, "offset", (long) offset,
                "level", LEVEL[level], "pn", pn, "epoch", epoch, "status", status, "sha256", hash));
    }

    private void close(String code, long offset, int ev, int pkt) {
        if (closed) {
            return;
        }
        closed = true;
        closeEvent = ev;
        closePacket = pkt;
        closeOffset = offset;
        closeCode = code;
    }

    private void accept(int level, long pn, Long epoch) {
        final Set<Long> set = seen.get(level);
        final long value = pn;
        set.add(value);
        journal.add(new Runnable() {
            @Override
            public void run() {
                set.remove(value);
            }
        });
        if (pn > largest[level]) {
            final int lvl = level;
            final long old = largest[level];
            largest[level] = pn;
            journal.add(new Runnable() {
                @Override
                public void run() {
                    largest[lvl] = old;
                }
            });
        }
        if (level != 2 || epoch == null) {
            return;
        }
        long[] st = epochs.get(epoch);
        if (st == null) {
            st = new long[] {pn, pn, 1};
            final long key = epoch;
            epochs.put(key, st);
            journal.add(new Runnable() {
                @Override
                public void run() {
                    epochs.remove(key);
                }
            });
        } else {
            final long[] f = st;
            final long oMin = f[0];
            final long oMax = f[1];
            final long oCount = f[2];
            journal.add(new Runnable() {
                @Override
                public void run() {
                    f[0] = oMin;
                    f[1] = oMax;
                    f[2] = oCount;
                }
            });
            if (pn < st[0]) {
                st[0] = pn;
            }
            if (pn > st[1]) {
                st[1] = pn;
            }
            st[2]++;
        }
        if (epoch == scal[S_EPOCH] + 1) {
            setScalar(S_EPOCH, epoch);
        }
    }

