    int code = (int) type;
    switch (code) {
        case 0x00: // PADDING: the single zero byte is the whole frame
        case 0x01: // PING
            return;
        case 0x02:
        case 0x03:
            ack(cur, out, level, code == 0x03);
            return;
        case 0x04:
            resetStream(cur, out);
            return;
        case 0x05:
            stopSending(cur, out);
            return;
        case 0x06:
            crypto(cur, out, level);
            return;
        case 0x08:
        case 0x09:
        case 0x0a:
        case 0x0b:
        case 0x0c:
        case 0x0d:
        case 0x0e:
        case 0x0f:
            stream(code, cur, out);
            return;
        case 0x10: { // MAX_DATA
            long maximum = cur.varint();
            out.writeBytes(vi(maximum));
            commitMaxData(maximum);
            return;
