    int block_segments = cfg_block_segments(ctx);
    uint32_t local = data_psn % (uint32_t)block_segments;
    uint32_t iter = data_psn / (uint32_t)block_segments;
    uint32_t ordinal = (uint32_t)ordinal_excluding(dest, src);
