        if op == 'or':
            return bool(left) or bool(self.visit(node.right))
        if op == 'implies':
            return (not bool(left)) or bool(self.visit(node.right))
        right = self.visit(node.right)
        if op == 'eq':
            return left == right
        if op == 'ne':
            return left != right
        if op == 'lt':
            return left < right
        if op == 'le':
            return left <= right
        if op == 'gt':
            return left > right
        if op == 'ge':
            return left >= right
        if op == 'add':
