    p = _skip_ws(s, pos)
    if p < n and s[p] == ";":
        if not allow_tag:
            raise BadSyntax()
        p += 1
        p = _skip_ws(s, p)
        start = p
        while p < n and s[p] in TOKEN_CHARS:
            p += 1
        if p == start:
            raise BadSyntax()
        name = s[start:p]
        if name.lower() != "tag":
            raise BadSyntax()
        p = _skip_ws(s, p)
        if p >= n or s[p] != "=":
            raise BadSyntax()
        p += 1
        p = _skip_ws(s, p)
        start = p
        while p < n and s[p] in TOKEN_CHARS:
            p += 1
        if p == start:
            raise BadSyntax()
        tag = s[start:p]
        if len(tag) > MAX_TAG_LEN:
            raise BadSyntax()
        pos = p
    else:
        pos = p
    return uri, tag, pos


def _parse_single_address(value, allow_tag):
    uri, tag, pos = _parse_address(value, 0, allow_tag)
    pos = _skip_ws(value, pos)
    if pos != len(value):
        raise BadSyntax()
    return uri, tag


def _parse_address_list(value):
    """Parse a comma separated address list (no header parameters)."""
    out = []
    pos = 0
    n = len(value)
    while True:
        uri, _tag, pos = _parse_address(value, pos, False)
        out.append(uri)
        pos = _skip_ws(value, pos)
        if pos >= n:
            break
        if value[pos] != ",":
            raise BadSyntax()
        pos = _skip_ws(value, pos)
        if pos >= n or value[pos] == ",":
            raise BadSyntax()
    return out


# ------------------------------------------------------------- header layer

def _split_header_line(line):
    n = len(line)
    i = 0
    while i < n and line[i] in TOKEN_CHARS:
        i += 1
    if i == 0:
        raise BadSyntax()
    name = line[:i]
    j = _skip_ws(line, i)
    if j >= n or line[j] != ":":
        raise BadSyntax()
    return name, line[j + 1:]


class Request(object):
    __slots__ = ("method", "ruri", "from_uri", "from_tag", "to_uri", "to_tag",
                 "call_id", "cseq", "privacy", "ppi", "rpid", "pai", "ctype",
                 "body")


def _parse_request(text):
    if len(text) > MAX_REQUEST_CHARS:
        raise BadSyntax()
    idx = text.find("\r\n\r\n")
    if idx < 0:
        raise BadSyntax()
    head = text[:idx]
    body = text[idx + 4:]
