        int size() {
            return list.size();
        }

        boolean isEmpty() {
            return list.isEmpty();
        }

        ArrayList<long[]> intervals() {
            return list;
        }

        long cardinality() {
            long total = 0;
            for (long[] range : list) {
                total += range[1] - range[0];
