  private boolean epochOrderingViolated(long pn, long generation) {
    for (Map.Entry<Long,long[]> e : epochs.entrySet()) {
      long epoch = e.getKey();
      if (epoch == generation) continue;
      long[] minMax = e.getValue();
      if (epoch > generation) { if (pn >= minMax[0]) return true; }
      else { if (pn <= minMax[1]) return true; }
    }
    return false;
  }
