  private void newConnectionId(Frame f) {
    byte[][] previous = peerObserved.get(f.sequence);
    if (previous != null && (!Arrays.equals(previous[0], f.data) || !Arrays.equals(previous[1], f.token))) throw new Fail(PROTOCOL_VIOLATION);
    Long owner = peerOwner.get(new AuditIo.ByteKey(f.data));
    if (owner != null && owner != f.sequence) throw new Fail(PROTOCOL_VIOLATION);
    if (previous == null) {
      peerObserved.put(f.sequence, new byte[][]{f.data, f.token});
      journal.push(() -> peerObserved.remove(f.sequence));
    }
    if (owner == null) {
      peerOwner.put(new AuditIo.ByteKey(f.data), f.sequence);
      final AuditIo.ByteKey key = new AuditIo.ByteKey(f.data);
      journal.push(() -> peerOwner.remove(key));
    }
    long threshold = Math.max(retirePriorTo, f.retirePriorTo);
    if (threshold != retirePriorTo) {
      long old = retirePriorTo;
      retirePriorTo = threshold;
      journal.push(() -> retirePriorTo = old);
      for (java.util.Iterator<Long> it = peerActive.iterator(); it.hasNext(); ) {
        long sequence = it.next();
        if (sequence >= threshold) break;
        it.remove();
        journal.push(() -> peerActive.add(sequence));
      }
    }
    if (f.sequence >= retirePriorTo && !peerActive.contains(f.sequence)) {
      peerActive.add(f.sequence);
      journal.push(() -> peerActive.remove(f.sequence));
    }
