        if (frameType == QuicFrameType.STREAM_FRAME_OFF
                || frameType == QuicFrameType.STREAM_FRAME_OFF_FIN
                || frameType == QuicFrameType.STREAM_FRAME_OFF_LEN
                || frameType == QuicFrameType.STREAM_FRAME_OFF_LEN_FIN) {
