                                          'seen': len(ep['seq']),
                                          'class': predict(banks[ep['bank']]['nodes'], feats),
                                          'reason': 'idle', 'rule': None, 'start': None})
                        ep['classified'] = True
                    else:
                        if ep['dir'] is None:
                            ep['dir'] = src
                        v = PADDING + length if src == ep['dir'] else PADDING - length
                        ep['seq'].append(v)
