                                              'release': ep['bank'], 'at': at,
                                              'seen': len(ep['seq']),
                                              'class': predict(banks[ep['bank']]['nodes'], feats),
                                              'reason': 'limit', 'rule': None, 'start': None})
                            ep['classified'] = True
                ep['ts'] = ts
            else:  # close
                fid = op[1]
