            index += 1
            key = row[1]
            revision = row[2]
            content = row[3]
            state = states.get(key)
            if state is None:
                states[key] = [revision, {content}]
            elif revision > state[0]:
                state[0] = revision
                state[1] = {content}
            elif revision == state[0]:
                state[1].add(content)
        self.index = index

    def visible(self):
        """Return ``((live, deleted, conflict), icmp_rows, app_rows)`` at this point."""
        live = deleted = conflict = 0
        icmp = []
        app = []
        for state in self.states.values():
            contents = state[1]
            if len(contents) > 1:
                conflict += 1
