                    cand.add(rec['s'])
                if rec['e'] > self.now:
                    cand.add(rec['e'])
        return sorted(cand)

    def _ticks_in_window(self, s, e):
        cand = {s}
        for rec in self.leases.values():
            if rec['state'] == 'live' and s < rec['s'] < e:
                cand.add(rec['s'])
        return sorted(cand)

