           'active_requests': [{'id': k, 'active': active[k]} for k in sorted(active)],
           'plan': {'resolved': amount, 'cost': spend, 'assignments': []}}
    return out

def plan_ref(job, active, leases):
    """Optimal objective via NetworkX min-cost flow; assignments unchecked here."""
    import networkx as nx
    G = nx.DiGraph()
    SRC, SNK = '@src', '@snk'
    G.add_node(SRC); G.add_node(SNK)
    for row in job['request_quotas']:
        if row['parent'] is None:
            G.add_edge(SRC, ('rq', row['id']), capacity=row['capacity'], weight=0)
        else:
            G.add_edge(('rq', row['parent']), ('rq', row['id']),
                       capacity=row['capacity'], weight=0)
    for r in job['requests']:
        G.add_edge(('rq', r['group']), ('r', r['id']), capacity=1, weight=0)
    pairs = []
    for off in job['offers']:
        net = ipaddress.IPv6Network(off['prefix'], strict=True)
        for rid in off['requests']:
            req = next(x for x in job['requests'] if x['id'] == rid)
            if not active[rid]:
                continue
            if req['service'] != off['service']:
                continue
            if not (req['at'] <= off['time'] < leases[req['lease']]['end']):
                continue
            if a2i(req['target']) not in net:
                continue
            pairs.append((rid, off['id']))
            G.add_edge(('r', rid), ('o', off['id']), capacity=1, weight=off['cost'])
    for off in job['offers']:
        G.add_edge(('o', off['id']), ('oq', off['group']),
                   capacity=off['capacity'], weight=0)
    for row in job['offer_quotas']:
        if row['parent'] is None:
            G.add_edge(('oq', row['id']), SNK, capacity=row['capacity'], weight=0)
        else:
            G.add_edge(('oq', row['id']), ('oq', row['parent']),
                       capacity=row['capacity'], weight=0)
    value, _ = nx.maximum_flow(G, SRC, SNK)
    for n in G.nodes:
        G.nodes[n]['demand'] = 0
    G.nodes[SRC]['demand'] = -value
    G.nodes[SNK]['demand'] = value
    flow = nx.min_cost_flow(G, demand='demand', capacity='capacity', weight='weight')
    amount = 0
    spend = 0
    for rid, oid in pairs:
        if flow.get(('r', rid), {}).get(('o', oid), 0):
            amount += 1
            spend += next(x['cost'] for x in job['offers'] if x['id'] == oid)
    return amount, spend
