    mode = spec[0]
    if mode == 'clos':
        _, k, scope, intra = spec
        r = k//2; T = k*r; n = k*k
        tors = list(range(T))
        tmpl = []
        for s in tors:
            for d in tors:
                if s == d: continue
                if not intra and s//r == d//r: continue
                fp = {s, d}
                for off in range(r):
                    fp.add(T + (s//r)*r + off)
                    fp.add(T + (d//r)*r + off)
                tmpl.append((s, d, sorted(fp)))
        dom = [(s if scope == 'tor' else s//r) for (s, d, f) in tmpl]
        return n, tmpl, dom
    if mode == 'leaf-spine':
        _, leaves, spines = spec
