cat > /workspace/dev/topo.py <<'PYEOF'
"""Independent Python implementation of the documented topology templates.

build(spec) -> (num_nodes, templates, domains) with templates a list of
(src, dst, sorted_footprint) in ascending source-then-destination order.
"""
from collections import deque

FNV_OFFSET = 0xcbf29ce484222325
FNV_PRIME = 0x100000001b3
MASK64 = (1 << 64) - 1


def fnv(data: bytes, seed: int = FNV_OFFSET) -> int:
    h = seed
    for b in data:
        h ^= b
        h = (h * FNV_PRIME) & MASK64
    return h


def _bfs(adj, n, src):
    dist = [-1] * n
    dist[src] = 0
    q = deque([src])
    while q:
        u = q.popleft()
        du = dist[u] + 1
        for v in adj[u]:
            if dist[v] < 0:
                dist[v] = du
                q.append(v)
    return dist


def _levels(dist, n):
    top = max(dist)
    levels = [0] * (top + 1)
    for v in range(n):
        levels[dist[v]] |= 1 << v
    return levels


def _mask_nodes(mask):
    out = []
    bit = 0
    while mask:
        if mask & 1:
            out.append(bit)
        mask >>= 1
        bit += 1
    return out


def _pair_templates(n, adj, endpoints):
    dists = [_bfs(adj, n, s) for s in range(n)]
    levels = [_levels(dists[s], n) for s in range(n)]
    tmpl = []
    for s in endpoints:
        ds = dists[s]
        ls = levels[s]
        for t in endpoints:
            if s == t:
                continue
            best = ds[t]
            lt = levels[t]
            mask = 0
            for k in range(best + 1):
                mask |= ls[k] & lt[best - k]
            tmpl.append((s, t, _mask_nodes(mask)))
    return tmpl


def build(spec):
    mode = spec[0]
    if mode == 'clos':
        _, k, scope, intra = spec
        r = k // 2
        T = k * r
        n = k * k
        tmpl = []
        for s in range(T):
            sp = s // r
            aggs = [T + sp * r + o for o in range(r)]
            for d in range(T):
                if s == d:
                    continue
                dp = d // r
                if not intra and sp == dp:
                    continue
                if sp == dp:
                    fp = sorted(set([s, d] + aggs))
                else:
                    fp = sorted(set([s, d] + aggs + [T + dp * r + o for o in range(r)]))
                tmpl.append((s, d, fp))
        dom = [(s if scope == 'tor' else s // r) for (s, d, f) in tmpl]
        return n, tmpl, dom
    if mode == 'leaf-spine':
        _, leaves, spines = spec
        n = leaves + spines
        tmpl = []
        dom = []
        for s in range(leaves):
            for d in range(leaves):
                if s == d:
                    continue
                tmpl.append((s, d, sorted([s, d])))
                dom.append(s)
        return n, tmpl, dom
    if mode in ('torus2d', 'torus3d'):
        _, side, scope = spec
        dim = 2 if mode == 'torus2d' else 3
        n = side ** dim
        adj = [[] for _ in range(n)]
        for u in range(n):
            c = []
            x = u
            for _ in range(dim):
                c.append(x % side)
                x //= side
            for ax in range(dim):
                for step in (1, side - 1):
                    c2 = list(c)
                    c2[ax] = (c2[ax] + step) % side
                    v = 0
                    for i in range(dim - 1, -1, -1):
                        v = v * side + c2[i]
                    if v != u:
                        adj[u].append(v)
        for a in adj:
            a = sorted(set(a))
        tmpl = _pair_templates(n, adj, range(n))
        dom = []
        for (s, d, f) in tmpl:
            y = (s // side) % side
            z = s // (side * side)
            if scope == 'host':
                dom.append(s)
            elif scope == 'row':
                dom.append(y)
            else:
                dom.append(z * side + y)
        return n, tmpl, dom
    if mode == 'dragonfly':
        _, g, a, h, scope = spec
        n = g * a
        adj = [[] for _ in range(n)]
        rid = lambda grp, i: grp * a + i
        for grp in range(g):
            base = grp * a
            for i in range(a):
                for j in range(i + 1, a):
                    adj[base + i].append(base + j)
                    adj[base + j].append(base + i)
        for i in range(g):
            for j in range(i + 1, g):
                delta = j - i
                u = rid(i, (delta - 1) // h)
                v = rid(j, (g - delta - 1) // h)
                adj[u].append(v)
                adj[v].append(u)
        tmpl = _pair_templates(n, adj, range(n))
        dom = []
        for (s, d, f) in tmpl:
            if scope == 'router':
                dom.append(s)
            elif scope == 'group':
                dom.append(s // a)
            else:
                dom.append(s * g + d // a)
        return n, tmpl, dom
    if mode == 'dragonfly-plus':
        _, g, l, s, h, dense, scope = spec
        per = l + s
        n = g * per
        leaf_id = lambda grp, i: grp * per + i
        spine_id = lambda grp, i: grp * per + l + i
        adj = [[] for _ in range(n)]
        for grp in range(g):
            for i in range(l):
                for j in range(s):
                    u = leaf_id(grp, i)
                    v = spine_id(grp, j)
                    adj[u].append(v)
                    adj[v].append(u)
        if dense:
            for i in range(g):
                for j in range(i + 1, g):
                    for k in range(s):
                        u = spine_id(i, k)
                        v = spine_id(j, k)
                        adj[u].append(v)
