        for lease_id in lease_ids:
            lease = leases[lease_id]
            is_active = lease['start'] <= query < lease['end']

            internal = set()
            external = set()
            internal_witness = {}
            external_witness = {}
            conflicts = []

            if not is_active:
                state = 'inactive'
                unresolved = []
            else:
                alias = False
                for record in icmp_by_lease[lease_id]:
