pub fn build_torus2d(
    n: usize,
    cap: usize,
    source_group_scope: Torus2DSourceGroupScope,
) -> TopologyCase {
    if n < 3 {
        panic!("--n must be at least 3");
    }

    let num_nodes = n * n;
    let mut demands = Vec::with_capacity(num_nodes * (num_nodes - 1));
    let mut path_lengths = BTreeMap::<usize, usize>::new();
    let mut footprint_sizes = BTreeMap::<usize, usize>::new();

    for src in 0..num_nodes {
        let (sx, sy) = node_xy(src, n);
        for dst in 0..num_nodes {
            if src == dst {
                continue;
            }
            let (dx, dy) = node_xy(dst, n);
            let x_paths = axis_shortest_paths(sx, dx, n);
            let y_paths = axis_shortest_paths(sy, dy, n);
            let shortest = x_paths[0].len() + y_paths[0].len() - 2;

            let mut in_footprint = vec![false; num_nodes];
            let mut footprint = Vec::new();
            for x_path in &x_paths {
                for y_path in &y_paths {
                    for &y in y_path {
                        for &x in x_path {
                            let node = node_id(x, y, n);
                            if !in_footprint[node] {
                                in_footprint[node] = true;
                                footprint.push(node);
                            }
                        }
                    }
                }
            }
            footprint.sort_unstable();

            *path_lengths.entry(shortest).or_insert(0) += 1;
            *footprint_sizes.entry(footprint.len()).or_insert(0) += 1;
            demands.push(Demand {
                src,
                dst,
                footprint,
            });
        }
    }

    let source_merge_groups = match source_group_scope {
        Torus2DSourceGroupScope::Row => {
            let mut groups = Vec::with_capacity(n);
            for y in 0..n {
                let mut group = Vec::with_capacity(n);
                for x in 0..n {
                    group.push(node_id(x, y, n));
                }
                groups.push(group);
            }
            groups
        }
        Torus2DSourceGroupScope::Host => (0..num_nodes).map(|node| vec![node]).collect(),
    };

    let mut cyclic_groups = Vec::with_capacity(n);
    for y in 0..n {
        let mut row = Vec::with_capacity(n);
        for x in 0..n {
            row.push(node_id(x, y, n));
        }
        cyclic_groups.push(row);
    }

    TopologyCase {
        name: format!("torus2d-n{}", n),
        problem: SolverProblem {
            num_nodes,
            capacities: vec![cap; num_nodes],
            demands,
            source_merge_groups,
            demand_merge_classes: None,
            symmetry: Some(SymmetrySpec { cyclic_groups }),
        },
        meta: TopologyMeta::Torus2D {
            n,
            cap,
            source_group_scope,
            path_lengths,
            footprint_sizes,
        },
    }
}

fn axis_shortest_paths(src: usize, dst: usize, n: usize) -> Vec<Vec<usize>> {
    let forward = (dst + n - src) % n;
    let backward = (src + n - dst) % n;

    if forward == 0 {
        return vec![vec![src]];
    }
    if forward < backward {
        return vec![axis_path(src, forward, 1, n)];
    }
    if backward < forward {
        return vec![axis_path(src, backward, -1, n)];
    }

    vec![
        axis_path(src, forward, 1, n),
        axis_path(src, backward, -1, n),
    ]
}

fn axis_path(src: usize, steps: usize, dir: isize, n: usize) -> Vec<usize> {
    let mut path = Vec::with_capacity(steps + 1);
    for step in 0..=steps {
        let offset = step as isize * dir;
        path.push(((src as isize + offset).rem_euclid(n as isize)) as usize);
    }
    path
}

fn node_id(x: usize, y: usize, n: usize) -> usize {
    y * n + x
}

fn node_xy(node: usize, n: usize) -> (usize, usize) {
    (node % n, node / n)
}


use std::collections::{BTreeMap, VecDeque};

use crate::solver::{Demand, SolverProblem, SymmetrySpec};

use super::{TopologyCase, TopologyMeta};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Torus3DSourceGroupScope {
    Line,
    Host,
}

impl Torus3DSourceGroupScope {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Line => "line",
            Self::Host => "host",
        }
    }
}

pub fn build_torus3d(
    n: usize,
    cap: usize,
    source_group_scope: Torus3DSourceGroupScope,
) -> TopologyCase {
    if n < 3 {
        panic!("--n must be at least 3");
    }

    let num_nodes = n * n * n;
    let adj = build_adjacency(n);
    let mut all_dist = Vec::with_capacity(num_nodes);
    for src in 0..num_nodes {
        all_dist.push(bfs(&adj, src));
    }

    let mut demands = Vec::with_capacity(num_nodes * (num_nodes - 1));
    let mut path_lengths = BTreeMap::<usize, usize>::new();
    let mut footprint_sizes = BTreeMap::<usize, usize>::new();
    for src in 0..num_nodes {
        for dst in 0..num_nodes {
            if src == dst {
                continue;
            }
            let shortest = all_dist[src][dst];
            let mut footprint = Vec::new();
            for node in 0..num_nodes {
                if all_dist[src][node] >= 0
                    && all_dist[dst][node] >= 0
                    && all_dist[src][node] + all_dist[dst][node] == shortest
                {
                    footprint.push(node);
                }
            }
            *path_lengths.entry(shortest as usize).or_insert(0) += 1;
            *footprint_sizes.entry(footprint.len()).or_insert(0) += 1;
            demands.push(Demand {
                src,
                dst,
                footprint,
            });
        }
    }

    let source_merge_groups = match source_group_scope {
        Torus3DSourceGroupScope::Line => {
            let mut groups = Vec::with_capacity(n * n);
            for z in 0..n {
                for y in 0..n {
                    let mut group = Vec::with_capacity(n);
                    for x in 0..n {
                        group.push(node_id(x, y, z, n));
                    }
                    groups.push(group);
                }
            }
            groups
        }
        Torus3DSourceGroupScope::Host => (0..num_nodes).map(|node| vec![node]).collect(),
    };

    let mut cyclic_groups = Vec::with_capacity(n);
    for z in 0..n {
        let mut plane = Vec::with_capacity(n * n);
        for y in 0..n {
            for x in 0..n {
                plane.push(node_id(x, y, z, n));
            }
        }
        cyclic_groups.push(plane);
    }

    TopologyCase {
        name: format!("torus3d-n{}", n),
        problem: SolverProblem {
            num_nodes,
            capacities: vec![cap; num_nodes],
            demands,
            source_merge_groups,
            demand_merge_classes: None,
            symmetry: Some(SymmetrySpec { cyclic_groups }),
        },
        meta: TopologyMeta::Torus3D {
            n,
            cap,
            source_group_scope,
            path_lengths,
            footprint_sizes,
        },
    }
}



fn build_adjacency(n: usize) -> Vec<Vec<usize>> {
    let num_nodes = n * n * n;
    let mut adj = vec![Vec::<usize>::new(); num_nodes];
    for z in 0..n {
        for y in 0..n {
            for x in 0..n {
                let u = node_id(x, y, z, n);
                for (dx, dy, dz) in [(1, 0, 0), (0, 1, 0), (0, 0, 1)] {
                    let v = node_id((x + dx) % n, (y + dy) % n, (z + dz) % n, n);
                    adj[u].push(v);
                    adj[v].push(u);
                }
            }
        }
    }
    for neigh in &mut adj {
        neigh.sort_unstable();
        neigh.dedup();
    }
    adj
}

fn node_id(x: usize, y: usize, z: usize, n: usize) -> usize {
    (z * n + y) * n + x
}

fn bfs(adj: &[Vec<usize>], src: usize) -> Vec<i32> {
    let mut dist = vec![-1i32; adj.len()];
    let mut q = VecDeque::new();
    dist[src] = 0;
    q.push_back(src);
    while let Some(node) = q.pop_front() {
        for &next in &adj[node] {
            if dist[next] < 0 {
                dist[next] = dist[node] + 1;
                q.push_back(next);
            }
        }
    }
    dist
}

use std::collections::{BTreeMap, HashMap, VecDeque};
use std::time::Instant;

use crate::solver::{Demand, SolverProblem, SymmetrySpec};

use super::{TopologyCase, TopologyMeta};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum DragonflySourceGroupScope {
    Group,
    Router,
    SourceTargetGroup,
}

impl DragonflySourceGroupScope {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Group => "group",
            Self::Router => "router",
            Self::SourceTargetGroup => "source-target-group",
        }
    }
}

pub fn build_dragonfly(
    groups: usize,
    routers_per_group: usize,
    global_links_per_router: usize,
    cap: Option<usize>,
    capacity_scale: f64,
    group_size_limit: usize,
    build_log_every: usize,
    source_group_scope: DragonflySourceGroupScope,
) -> TopologyCase {
    if groups - 1 != routers_per_group * global_links_per_router {
        panic!(
            "canonical dragonfly requires groups - 1 == routers_per_group * global_links_per_router"
        );
    }
    let num_nodes = groups * routers_per_group;
    let router_group: Vec<usize> = (0..num_nodes).map(|id| id / routers_per_group).collect();
    let adj = build_adjacency(groups, routers_per_group, global_links_per_router);
    let build_start = Instant::now();

    let mut all_dist = Vec::with_capacity(num_nodes);
    for src in 0..num_nodes {
        all_dist.push(bfs(&adj, src));
        if build_log_every > 0 && (src + 1) % build_log_every == 0 {
            println!(
                "build: bfs {}/{} elapsed_s={:.1}",
                src + 1,
                num_nodes,
                build_start.elapsed().as_secs_f64()
            );
        }
    }

    let mut demands = Vec::new();
    let mut path_lengths = BTreeMap::<usize, usize>::new();
    let mut footprint_sizes = BTreeMap::<usize, usize>::new();
    for src in 0..num_nodes {
        for dst in 0..num_nodes {
            if src == dst {
                continue;
            }
            let shortest = all_dist[src][dst];
            let mut footprint = Vec::new();
            for node in 0..num_nodes {
                if all_dist[src][node] >= 0
                    && all_dist[dst][node] >= 0
                    && all_dist[src][node] + all_dist[dst][node] == shortest
                {
                    footprint.push(node);
                }
            }
            *path_lengths.entry(shortest as usize).or_insert(0) += 1;
            *footprint_sizes.entry(footprint.len()).or_insert(0) += 1;
            demands.push(Demand {
                src,
                dst,
                footprint,
            });
            if build_log_every > 0 && demands.len() % build_log_every == 0 {
                println!(
                    "build: footprints {}/{} elapsed_s={:.1}",
                    demands.len(),
                    num_nodes * (num_nodes - 1),
                    build_start.elapsed().as_secs_f64()
                );
            }
        }
    }

    let natural_usage_max;
    let uniform_cap = if let Some(cap) = cap {
        natural_usage_max = None;
        cap
    } else {
        let natural_usage =
            dragonfly_natural_usage(num_nodes, &router_group, &demands, group_size_limit);
        let max_nat = natural_usage.into_iter().max().unwrap_or(0);
        natural_usage_max = Some(max_nat);
        ((max_nat as f64) * capacity_scale).ceil() as usize
    };
    let capacities = vec![uniform_cap; num_nodes];

    let mut cyclic_groups = Vec::with_capacity(groups);
    for group_id in 0..groups {
        let mut group = Vec::with_capacity(routers_per_group);
        for router in 0..routers_per_group {
            group.push(group_id * routers_per_group + router);
        }
        cyclic_groups.push(group);
    }
    let source_merge_groups = match source_group_scope {
        DragonflySourceGroupScope::Group => cyclic_groups.clone(),
        DragonflySourceGroupScope::Router | DragonflySourceGroupScope::SourceTargetGroup => {
            (0..num_nodes).map(|node| vec![node]).collect()
        }
    };
    let demand_merge_classes = match source_group_scope {
        DragonflySourceGroupScope::Group | DragonflySourceGroupScope::Router => None,
        DragonflySourceGroupScope::SourceTargetGroup => Some(
            demands
                .iter()
                .map(|demand| demand.src * groups + router_group[demand.dst])
                .collect(),
        ),
    };

    TopologyCase {
        name: format!(
            "dragonfly-g{}-a{}-h{}",
            groups, routers_per_group, global_links_per_router
        ),
        problem: SolverProblem {
            num_nodes,
            capacities,
            demands,
            source_merge_groups,
            demand_merge_classes,
            symmetry: Some(SymmetrySpec { cyclic_groups }),
        },
        meta: TopologyMeta::Dragonfly {
            groups,
            routers_per_group,
            global_links_per_router,
            path_lengths,
            footprint_sizes,
            uniform_cap,
            natural_usage_max,
            capacity_scale: cap.is_none().then_some(capacity_scale),
            source_group_scope,
        },
    }
}



fn build_adjacency(
    groups: usize,
    routers_per_group: usize,
    global_links_per_router: usize,
) -> Vec<Vec<usize>> {
    let num_nodes = groups * routers_per_group;
    let mut adj = vec![Vec::<usize>::new(); num_nodes];
    let rid = |group: usize, idx: usize| -> usize { group * routers_per_group + idx };
    let endpoint_idx = |delta: usize| -> usize { (delta - 1) / global_links_per_router };

    for group in 0..groups {
        for i in 0..routers_per_group {
            for j in (i + 1)..routers_per_group {
                let u = rid(group, i);
                let v = rid(group, j);
                adj[u].push(v);
                adj[v].push(u);
            }
        }
    }

    for g1 in 0..groups {
        for g2 in (g1 + 1)..groups {
            let delta = (g2 + groups - g1) % groups;
            let reverse_delta = groups - delta;
            let i1 = endpoint_idx(delta);
            let i2 = endpoint_idx(reverse_delta);
            let u = rid(g1, i1);
            let v = rid(g2, i2);
            adj[u].push(v);
            adj[v].push(u);
        }
    }

    for neigh in &mut adj {
        neigh.sort_unstable();
        neigh.dedup();
    }
    adj
}

fn bfs(adj: &[Vec<usize>], src: usize) -> Vec<i32> {
    let mut dist = vec![-1i32; adj.len()];
    let mut q = VecDeque::new();
    dist[src] = 0;
    q.push_back(src);
    while let Some(node) = q.pop_front() {
        for &next in &adj[node] {
            if dist[next] < 0 {
                dist[next] = dist[node] + 1;
                q.push_back(next);
            }
        }
    }
    dist
}

fn dragonfly_natural_usage(
    num_nodes: usize,
    router_group: &[usize],
    demands: &[Demand],
    group_size_limit: usize,
) -> Vec<usize> {
    let mut by_key = HashMap::<(usize, usize), Vec<usize>>::new();
    for (demand_id, demand) in demands.iter().enumerate() {
        by_key
            .entry((demand.src, router_group[demand.dst]))
            .or_default()
            .push(demand_id);
    }

    let mut usage = vec![0usize; num_nodes];
    for demand_ids in by_key.values() {
        let c = ceil_div(demand_ids.len(), group_size_limit);
        let mut footprint = vec![false; num_nodes];
        for &demand_id in demand_ids {
            for &node in &demands[demand_id].footprint {
                footprint[node] = true;
            }
        }
        for (node, used) in footprint.into_iter().enumerate() {
            if used {
                usage[node] += c;
            }
        }
    }
    usage
}

fn ceil_div(n: usize, d: usize) -> usize {
    ((n + d - 1) / d).max(1)
}

use std::collections::{BTreeMap, VecDeque};
use std::time::Instant;

use crate::solver::{Demand, SolverProblem, SymmetrySpec};

use super::{TopologyCase, TopologyMeta};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum DragonflyPlusSourceGroupScope {
    Group,
    Tor,
}

impl DragonflyPlusSourceGroupScope {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Group => "group",
            Self::Tor => "tor",
        }
    }
}

pub fn build_dragonfly_plus(
    groups: usize,
    leaves_per_group: usize,
    spines_per_group: usize,
    global_links_per_spine: usize,
    dense_global: bool,
    cap: usize,
    build_log_every: usize,
    source_group_scope: DragonflyPlusSourceGroupScope,
) -> TopologyCase {
    if groups < 2 {
        panic!("--groups must be at least 2");
    }
    if leaves_per_group == 0 {
        panic!("--leaves-per-group must be positive");
    }
    if spines_per_group == 0 {
        panic!("--spines-per-group must be positive");
    }
    let global_links_per_spine = if dense_global {
        groups - 1
    } else {
        global_links_per_spine
    };
    if global_links_per_spine == 0 {
        panic!("--global-links-per-spine must be positive");
    }
    if !dense_global && groups - 1 != spines_per_group * global_links_per_spine {
        panic!(
            "canonical dragonfly+ requires groups - 1 == spines_per_group * global_links_per_spine"
        );
    }

    let switches_per_group = leaves_per_group + spines_per_group;
    let leaves = groups * leaves_per_group;
    let spines = groups * spines_per_group;
    let num_nodes = groups * switches_per_group;
    let adj = build_adjacency(
        groups,
        leaves_per_group,
        spines_per_group,
        global_links_per_spine,
        dense_global,
    );
    let build_start = Instant::now();

    let mut leaf_nodes = Vec::with_capacity(leaves);
    for group in 0..groups {
        for leaf in 0..leaves_per_group {
            leaf_nodes.push(leaf_id(group, leaf, switches_per_group));
        }
    }

    let mut all_dist = Vec::with_capacity(num_nodes);
    for src in 0..num_nodes {
        all_dist.push(bfs(&adj, src));
        if build_log_every > 0 && (src + 1) % build_log_every == 0 {
            println!(
                "build: bfs {}/{} elapsed_s={:.1}",
                src + 1,
                num_nodes,
                build_start.elapsed().as_secs_f64()
            );
        }
    }

    let mut demands = Vec::with_capacity(leaves * (leaves - 1));
    let mut path_lengths = BTreeMap::<usize, usize>::new();
    let mut footprint_sizes = BTreeMap::<usize, usize>::new();
    for &src in &leaf_nodes {
        for &dst in &leaf_nodes {
            if src == dst {
                continue;
            }
            let shortest = all_dist[src][dst];
            let mut footprint = Vec::new();
            for node in 0..num_nodes {
                if all_dist[src][node] >= 0
                    && all_dist[dst][node] >= 0
                    && all_dist[src][node] + all_dist[dst][node] == shortest
                {
                    footprint.push(node);
                }
            }
            *path_lengths.entry(shortest as usize).or_insert(0) += 1;
            *footprint_sizes.entry(footprint.len()).or_insert(0) += 1;
            demands.push(Demand {
                src,
                dst,
                footprint,
            });
            if build_log_every > 0 && demands.len() % build_log_every == 0 {
                println!(
                    "build: footprints {}/{} elapsed_s={:.1}",
                    demands.len(),
                    leaves * (leaves - 1),
                    build_start.elapsed().as_secs_f64()
                );
            }
        }
    }

    let mut cyclic_groups = Vec::with_capacity(groups);
    let mut source_merge_groups = match source_group_scope {
        DragonflyPlusSourceGroupScope::Group => Vec::with_capacity(groups),
        DragonflyPlusSourceGroupScope::Tor => Vec::with_capacity(leaves),
    };
    for group in 0..groups {
        let group_start = group * switches_per_group;
        cyclic_groups.push((group_start..group_start + switches_per_group).collect());
        match source_group_scope {
            DragonflyPlusSourceGroupScope::Group => {
                source_merge_groups.push(
                    (0..leaves_per_group)
                        .map(|leaf| leaf_id(group, leaf, switches_per_group))
                        .collect(),
                );
            }
            DragonflyPlusSourceGroupScope::Tor => {
                for leaf in 0..leaves_per_group {
                    source_merge_groups.push(vec![leaf_id(group, leaf, switches_per_group)]);
                }
            }
        }
    }

    TopologyCase {
        name: format!(
            "dragonfly-plus{}-g{}-l{}-s{}-h{}",
            if dense_global { "-dense" } else { "" },
            groups,
            leaves_per_group,
            spines_per_group,
            global_links_per_spine
        ),
        problem: SolverProblem {
            num_nodes,
            capacities: vec![cap; num_nodes],
            demands,
            source_merge_groups,
            demand_merge_classes: None,
            symmetry: Some(SymmetrySpec { cyclic_groups }),
        },
        meta: TopologyMeta::DragonflyPlus {
            groups,
            leaves_per_group,
            spines_per_group,
            global_links_per_spine,
            dense_global,
            leaves,
            spines,
            cap,
            source_group_scope,
            path_lengths,
            footprint_sizes,
        },
    }
}



fn build_adjacency(
    groups: usize,
    leaves_per_group: usize,
    spines_per_group: usize,
    global_links_per_spine: usize,
    dense_global: bool,
) -> Vec<Vec<usize>> {
    let switches_per_group = leaves_per_group + spines_per_group;
    let num_nodes = groups * switches_per_group;
    let mut adj = vec![Vec::<usize>::new(); num_nodes];

    for group in 0..groups {
        for leaf in 0..leaves_per_group {
            for spine in 0..spines_per_group {
                add_edge(
                    &mut adj,
                    leaf_id(group, leaf, switches_per_group),
                    spine_id(group, spine, leaves_per_group, switches_per_group),
                );
            }
        }
    }

    if dense_global {
        for g1 in 0..groups {
            for g2 in (g1 + 1)..groups {
                for spine in 0..spines_per_group {
                    add_edge(
                        &mut adj,
                        spine_id(g1, spine, leaves_per_group, switches_per_group),
                        spine_id(g2, spine, leaves_per_group, switches_per_group),
                    );
                }
            }
        }
    } else {
        for g1 in 0..groups {
            for g2 in (g1 + 1)..groups {
                let delta = (g2 + groups - g1) % groups;
                let reverse_delta = groups - delta;
                let s1 = endpoint_spine(delta, global_links_per_spine);
                let s2 = endpoint_spine(reverse_delta, global_links_per_spine);
                add_edge(
                    &mut adj,
                    spine_id(g1, s1, leaves_per_group, switches_per_group),
                    spine_id(g2, s2, leaves_per_group, switches_per_group),
                );
            }
        }
    }

    for neigh in &mut adj {
        neigh.sort_unstable();
        neigh.dedup();
    }
    adj
}

fn leaf_id(group: usize, leaf: usize, switches_per_group: usize) -> usize {
    group * switches_per_group + leaf
}

fn spine_id(
    group: usize,
    spine: usize,
    leaves_per_group: usize,
    switches_per_group: usize,
) -> usize {
    group * switches_per_group + leaves_per_group + spine
}

fn endpoint_spine(delta: usize, global_links_per_spine: usize) -> usize {
    (delta - 1) / global_links_per_spine
}

fn add_edge(adj: &mut [Vec<usize>], u: usize, v: usize) {
    adj[u].push(v);
    adj[v].push(u);
}

fn bfs(adj: &[Vec<usize>], src: usize) -> Vec<i32> {
    let mut dist = vec![-1i32; adj.len()];
    let mut q = VecDeque::new();
    dist[src] = 0;
    q.push_back(src);
    while let Some(node) = q.pop_front() {
        for &next in &adj[node] {
            if dist[next] < 0 {
                dist[next] = dist[node] + 1;
                q.push_back(next);
            }
        }
    }
    dist
}

#!/usr/bin/env python3
"""Public executable sanity checks, with per-invocation descendant cleanup."""
import argparse
import ctypes
import json
import math
import os
import pathlib
import selectors
import signal
import subprocess
import sys
import time
from candidate_policy import candidate_setup

CANCELLED = 0
CLEANUP_SECONDS = 5

class CheckerInfrastructure(RuntimeError):
    pass

class Interrupted(RuntimeError):
    pass

def remember_signal(signum, frame):
    # Never raise from a signal handler: repeated signals cannot interrupt
    # group termination, waitpid, pipe closure, or reaping adopted descendants.
    global CANCELLED
    if not CANCELLED:
        CANCELLED = signum

def check_interruption():
    if CANCELLED:
        raise Interrupted('public checker interrupted')

def pairs(items):
    obj = {}
    for key, val in items:
        if key in obj:
            raise ValueError('duplicate output key')
        obj[key] = val
    return obj

def nonfinite(value):
    raise ValueError('nonfinite output')

def finite_float(value):
    parsed = float(value)
    if not math.isfinite(parsed):
        raise ValueError('nonfinite output')
    return parsed

def strict_load(raw):
    return json.loads(raw.decode('utf-8'), object_pairs_hook=pairs,
                      parse_constant=nonfinite, parse_float=finite_float)

def same(a, b):
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    return a == b

def prepare_supervisor():
    if os.uname().machine != 'x86_64':
        raise CheckerInfrastructure('x86_64 worker required')
    libc = ctypes.CDLL(None, use_errno=True)
    if libc.prctl(36, 1, 0, 0, 0):
        raise CheckerInfrastructure('child subreaper unavailable')
    try:
        # Signal 0 changes no process state. A scored-profile parent fails
        # here, before any candidate can inherit inadequate supervision.
        os.killpg(os.getpgrp(), 0)
    except OSError as exc:
        raise CheckerInfrastructure('trusted parent needs published checker profile') from exc

def child_finished(p):
    # WNOWAIT retains the leader's PID until its process group is killed;
    # Popen.poll() would reap it early and lose that group-ID anchor.
    info = os.waitid(os.P_PID, p.pid, os.WEXITED | os.WNOHANG | os.WNOWAIT)
    return info is not None

def terminate_and_reap(p):
    end = time.monotonic()+CLEANUP_SECONDS
    try:
        os.killpg(p.pid, signal.SIGKILL)
    except ProcessLookupError:
        pass
    except OSError as exc:
        raise CheckerInfrastructure('cannot terminate candidate process group') from exc
    try:
        p.wait(timeout=max(.001, end-time.monotonic()))
    except subprocess.TimeoutExpired as exc:
        raise CheckerInfrastructure('candidate leader cleanup deadline') from exc
    while True:
        try:
            pid, _ = os.waitpid(-p.pid, os.WNOHANG)
        except ChildProcessError:
            return
        except InterruptedError:
            continue
        if pid:
            continue
        # Ordinary descendants inherit this group and cannot call setsid or
        # setpgid after candidate_setup. Catch a fork concurrent with the first
        # group signal while a known adopted child still anchors the group.
        try:
            os.killpg(p.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        if time.monotonic() >= end:
            raise CheckerInfrastructure('descendant cleanup deadline')
        time.sleep(.002)

def execute(candidate, data):
    """Actual child pipes; session ownership is established before policy restore."""
    prepare_supervisor()
    check_interruption()
    env = {'PATH': os.environ.get('PATH', '/usr/local/bin:/usr/bin:/bin'),
           'LANG': 'C.UTF-8', 'HOME': '/workspace',
           'TMPDIR': os.environ.get('TMPDIR', '/workspace/tmp'),
           'PYTHONDONTWRITEBYTECODE': '1', 'PYTHONHASHSEED': '0',
           'OPENBLAS_NUM_THREADS': '1', 'OMP_NUM_THREADS': '1', 'MKL_NUM_THREADS': '1'}
    end = time.monotonic()+180
    try:
        p = subprocess.Popen([sys.executable, '-B', str(candidate)], stdin=subprocess.PIPE,
                             stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                             close_fds=True, env=env, start_new_session=True,
                             preexec_fn=candidate_setup)
    except (OSError, subprocess.SubprocessError) as exc:
        raise CheckerInfrastructure('candidate supervision/policy setup failed') from exc
    sel = selectors.DefaultSelector()
    streams = [p.stdin, p.stdout, p.stderr]
    output = [bytearray(), bytearray()]
    pos = 0

    def read_output(f, k):
        cap = (32*1024**2, 1024**2)[k]
        try:
            block = os.read(f.fileno(), min(65536, cap-len(output[k])+1))
        except BlockingIOError:
            return True
        if len(output[k])+len(block) > cap:
            raise ValueError('candidate output limit')
        output[k].extend(block)
        return bool(block)

    try:
        for f in streams:
            os.set_blocking(f.fileno(), False)
        if data:
            sel.register(p.stdin, selectors.EVENT_WRITE, -1)
        else:
            p.stdin.close()
        sel.register(p.stdout, selectors.EVENT_READ, 0)
        sel.register(p.stderr, selectors.EVENT_READ, 1)
        while not child_finished(p):
            check_interruption()
            if time.monotonic() >= end:
                raise ValueError('candidate wall limit')
            for key, _ in sel.select(.05):
                f, k = key.fileobj, key.data
                if k == -1:
                    try:
                        sent = os.write(f.fileno(), data[pos:pos+65536])
                    except BlockingIOError:
                        continue
                    except BrokenPipeError:
                        sel.unregister(f)
                        f.close()
                        continue
                    pos += sent
                    if pos == len(data):
                        sel.unregister(f)
                        f.close()
                elif not read_output(f, k):
                    sel.unregister(f)
                    f.close()
    finally:
        # This also runs on normal root return with detached descendants,
        # output/deadline rejection, abnormal exit, and all Python exceptions.
        try:
            terminate_and_reap(p)
            # Preserve explicitly written/flushed pipe bytes on os._exit(0).
            # Descendants are gone, so these pipes must reach EOF immediately.
            for k, f in enumerate([p.stdout, p.stderr]):
                if not f.closed:
                    while read_output(f, k):
                        pass
        finally:
            sel.close()
            for f in streams:
                f.close()
    check_interruption()
    if p.returncode != 0:
        raise ValueError('candidate nonzero exit')
    if not output[0].strip():
        raise ValueError('candidate empty output')
    return strict_load(bytes(output[0]))

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--candidate', default='submission/main.py')
    args = parser.parse_args()
    if os.geteuid() == 0:
        print('INFRASTRUCTURE: run this checker as nonroot inside the offline task environment.', file=sys.stderr)
        return 2
    signal.signal(signal.SIGTERM, remember_signal)
    signal.signal(signal.SIGINT, remember_signal)
    candidate = pathlib.Path(args.candidate).resolve()
    here = pathlib.Path(__file__).resolve().parent
    fixtures = json.loads((here/'examples/checks.json').read_text())
    try:
        for i, fixture in enumerate(fixtures):
            check_interruption()
            data = fixture.get('raw')
            if data is None:
                data = json.dumps(fixture['request'], separators=(',', ':'))
            try:
                result = execute(candidate, data.encode('utf-8'))
                if not same(result, fixture['response']):
                    raise ValueError('response mismatch')
            except (ValueError, OSError, RecursionError, OverflowError) as exc:
                check_interruption()
                print(f'FAIL public fixture {i}: {exc}')
                return 1
        check_interruption()
        print(f'PASS {len(fixtures)} public executable checks')
        return 128+CANCELLED if CANCELLED else 0
    except Interrupted:
        print('INTERRUPTED: candidate process group terminated and reaped', file=sys.stderr)
        return 128+CANCELLED
    except CheckerInfrastructure as exc:
        print(f'INFRASTRUCTURE: {exc}', file=sys.stderr)
        return 2

if __name__ == '__main__':
    raise SystemExit(main())
