    num_groups: usize,
    num_tasks: usize,
    fp_words: usize,
    caps: Vec<u64>,
    group_quota: Vec<u64>,
    group_budget: Vec<u64>,
    task_template: Vec<usize>,
    task_group: Vec<usize>,
    task_weight: Vec<u64>,
    task_class: Vec<u64>,
    task_pinned: Vec<bool>,
    tmpl_domain: Vec<i64>,
    tmpl_fp: Vec<u64>,
    group_members: Vec<u32>,
    group_load: Vec<u64>,
    group_pins: Vec<u32>,
    group_fp_size: Vec<u32>,
    group_counts: Vec<u32>,
    group_keys: Vec<HashMap<(i64, i64), u32>>,
    group_domain: Vec<i64>,
    group_class: Vec<i64>,
    usage: Vec<i64>,
