impl Ledger {
    pub fn new(
        problem: &SolverProblem,
        tasks: Vec<Task>,
        quotas: Vec<u64>,
        budgets: Vec<u64>,
        capacities: Vec<u64>,
    ) -> Result<Self, String> {
