using Key = unsigned __int128;

inline std::string hexkey(Key x) {
    static const char* d = "0123456789abcdef";
    std::string s(32, '0');
    for (int i = 31; i >= 0; --i) { s[i] = d[unsigned(x & 15)]; x >>= 4; }
    return s;
}

inline int hexval(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

inline Key key(const std::string& s) {
    if (s.empty() || s.size() > 32) throw std::runtime_error("key width");
    Key v = 0;
    for (char c : s) { int d = hexval(c); if (d < 0) throw std::runtime_error("key digit"); v = (v << 4) | d; }
    return v;
}
