    while True:
        try:
            pid, _ = os.waitpid(-p.pid, os.WNOHANG)
        except ChildProcessError:
            return
        except InterruptedError:
            continue
        if pid:
            continue
        # Ordinary descendants inherit this group and cannot call setsid or
        # setpgid after candidate_setup. Catch a fork concurrent with the first
        # group signal while a known adopted child still anchors the group.
        try:
            os.killpg(p.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        if time.monotonic() >= end:
            raise CheckerInfrastructure('descendant cleanup deadline')
        time.sleep(.002)

def execute(candidate, data):
    """Actual child pipes; session ownership is established before policy restore."""
    prepare_supervisor()
    check_interruption()
    env = {'PATH': os.environ.get('PATH', '/usr/local/bin:/usr/bin:/bin'),
           'LANG': 'C.UTF-8', 'HOME': '/workspace',
           'TMPDIR': os.environ.get('TMPDIR', '/workspace/tmp'),
           'PYTHONDONTWRITEBYTECODE': '1', 'PYTHONHASHSEED': '0',
           'OPENBLAS_NUM_THREADS': '1', 'OMP_NUM_THREADS': '1', 'MKL_NUM_THREADS': '1'}
    end = time.monotonic()+180
    try:
        p = subprocess.Popen([sys.executable, '-B', str(candidate)], stdin=subprocess.PIPE,
                             stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                             close_fds=True, env=env, start_new_session=True,
                             preexec_fn=candidate_setup)
    except (OSError, subprocess.SubprocessError) as exc:
        raise CheckerInfrastructure('candidate supervision/policy setup failed') from exc
    sel = selectors.DefaultSelector()
    streams = [p.stdin, p.stdout, p.stderr]
    output = [bytearray(), bytearray()]
    pos = 0

    def read_output(f, k):
        cap = (32*1024**2, 1024**2)[k]
        try:
            block = os.read(f.fileno(), min(65536, cap-len(output[k])+1))
        except BlockingIOError:
            return True
        if len(output[k])+len(block) > cap:
            raise ValueError('candidate output limit')
        output[k].extend(block)
        return bool(block)

    try:
        for f in streams:
            os.set_blocking(f.fileno(), False)
        if data:
            sel.register(p.stdin, selectors.EVENT_WRITE, -1)
        else:
            p.stdin.close()
        sel.register(p.stdout, selectors.EVENT_READ, 0)
        sel.register(p.stderr, selectors.EVENT_READ, 1)
        while not child_finished(p):
            check_interruption()
            if time.monotonic() >= end:
                raise ValueError('candidate wall limit')
            for key, _ in sel.select(.05):
                f, k = key.fileobj, key.data
                if k == -1:
                    try:
                        sent = os.write(f.fileno(), data[pos:pos+65536])
                    except BlockingIOError:
                        continue
                    except BrokenPipeError:
                        sel.unregister(f)
                        f.close()
                        continue
                    pos += sent
                    if pos == len(data):
                        sel.unregister(f)
                        f.close()
                elif not read_output(f, k):
                    sel.unregister(f)
                    f.close()
    finally:
        # This also runs on normal root return with detached descendants,
        # output/deadline rejection, abnormal exit, and all Python exceptions.
        try:
            terminate_and_reap(p)
            # Preserve explicitly written/flushed pipe bytes on os._exit(0).
            # Descendants are gone, so these pipes must reach EOF immediately.
            for k, f in enumerate([p.stdout, p.stderr]):
                if not f.closed:
                    while read_output(f, k):
                        pass
        finally:
            sel.close()
            for f in streams:
                f.close()
    check_interruption()
    if p.returncode != 0:
        raise ValueError('candidate nonzero exit')
    if not output[0].strip():
        raise ValueError('candidate empty output')
    return strict_load(bytes(output[0]))

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--candidate', default='submission/main.py')
    args = parser.parse_args()
    if os.geteuid() == 0:
        print('INFRASTRUCTURE: run this checker as nonroot inside the offline task environment.', file=sys.stderr)
        return 2
    signal.signal(signal.SIGTERM, remember_signal)
    signal.signal(signal.SIGINT, remember_signal)
    candidate = pathlib.Path(args.candidate).resolve()
    here = pathlib.Path(__file__).resolve().parent
    fixtures = json.loads((here/'examples/checks.json').read_text())
    try:
        for i, fixture in enumerate(fixtures):
            check_interruption()
            data = fixture.get('raw')
            if data is None:
                data = json.dumps(fixture['request'], separators=(',', ':'))
            try:
                result = execute(candidate, data.encode('utf-8'))
                if not same(result, fixture['response']):
                    raise ValueError('response mismatch')
            except (ValueError, OSError, RecursionError, OverflowError) as exc:
                check_interruption()
                print(f'FAIL public fixture {i}: {exc}')
                return 1
        check_interruption()
        print(f'PASS {len(fixtures)} public executable checks')
        return 128+CANCELLED if CANCELLED else 0
    except Interrupted:
        print('INTERRUPTED: candidate process group terminated and reaped', file=sys.stderr)
        return 128+CANCELLED
    except CheckerInfrastructure as exc:
        print(f'INFRASTRUCTURE: {exc}', file=sys.stderr)
        return 2

if __name__ == '__main__':
    raise SystemExit(main())

use std::io::{self, Read};
use rust_unit_merge::ledger::{Task,Edit,Query,Certificate,Ledger};
use rust_unit_merge::topology::*;

struct Input { words:Vec<String>, at:usize }
impl Input {
 fn next(&mut self)->Result<String,String> {if self.at>=self.words.len(){return Err("truncated".into());}let s=self.words[self.at].clone();self.at+=1;Ok(s)}
 fn n(&mut self)->Result<usize,String>{self.next()?.parse().map_err(|_|"integer".into())}
 fn u(&mut self)->Result<u64,String>{self.next()?.parse().map_err(|_|"integer".into())}
 fn ids(&mut self)->Result<Vec<usize>,String>{let n=self.n()?;(0..n).map(|_|self.n()).collect()}
 fn query(&mut self)->Result<Query,String>{Ok(Query{groups:self.ids()?,nodes:self.ids()?,tasks:self.ids()?})}
}
fn topology(i:&mut Input)->Result<TopologyCase,String>{
 let code=i.n()?; let args=(0..7).map(|_|i.n()).collect::<Result<Vec<_>,_>>()?;
 Ok(match code {
  0=>build_clos(args[0],1,None,None,args[2]!=0,if args[1]==0 {ClosSourceGroupScope::Tor}else{ClosSourceGroupScope::Pod}),
  1=>build_leaf_spine(args[0],args[1],1),
  2=>build_torus2d(args[0],1,if args[1]==0 {Torus2DSourceGroupScope::Host}else{Torus2DSourceGroupScope::Row}),
  3=>build_torus3d(args[0],1,if args[1]==0 {Torus3DSourceGroupScope::Host}else{Torus3DSourceGroupScope::Line}),
  4=>build_dragonfly(args[0],args[1],args[2],Some(1),1.0,1,0,match args[3]{0=>DragonflySourceGroupScope::Router,1=>DragonflySourceGroupScope::Group,_=>DragonflySourceGroupScope::SourceTargetGroup}),
  5=>build_dragonfly_plus(args[0],args[1],args[2],args[3],args[4]!=0,1,0,if args[5]==0{DragonflyPlusSourceGroupScope::Tor}else{DragonflyPlusSourceGroupScope::Group}),
  _=>return Err("topology".into()),
 })
}
fn array<T:std::fmt::Display>(row:&[T])->String{format!("[{}]",row.iter().map(|x|x.to_string()).collect::<Vec<_>>().join(","))}
fn rows<T:std::fmt::Display,const N:usize>(data:&[[T;N]])->String{format!("[{}]",data.iter().map(|x|array(x)).collect::<Vec<_>>().join(","))}
fn certificate(c:Certificate)->String{format!("{{\"totals\":{},\"groups\":{},\"nodes\":{},\"tasks\":{}}}",array(&c.totals),rows(&c.groups),rows(&c.nodes),rows(&c.tasks))}
fn run(i:&mut Input)->Result<String,String>{
 let sessions=i.n()?;let mut output=Vec::new();
 for _ in 0..sessions {
  let case=topology(i)?;let task_count=i.n()?;let group_count=i.n()?;
  let caps=(0..case.problem.num_nodes).map(|_|i.u()).collect::<Result<Vec<_>,_>>()?;
  let mut quotas=Vec::new();let mut budgets=Vec::new();
  for _ in 0..group_count{quotas.push(i.u()?);budgets.push(i.u()?);}
  let mut tasks=Vec::new();
  for _ in 0..task_count{tasks.push(Task{template:i.n()?,group:i.n()?,weight:i.u()?,class:i.u()?,pinned:i.n()?!=0});}
  let mut ledger=Ledger::new(&case.problem,tasks,quotas,budgets,caps)?;
  let initial=certificate(ledger.certificate(&i.query()?));
  let transactions=i.n()?;let mut results=Vec::new();
  for _ in 0..transactions{
   let expected=i.u()?;let operations=i.n()?;let mut edits=Vec::new();
   for _ in 0..operations{
    let op=i.n()?;let id=i.n()?;let value=i.u()?;
    edits.push(match op{0=>Edit::Move(id,value as usize),1=>Edit::Weight(id,value),2=>Edit::Class(id,value),3=>Edit::Bind(id,value as usize),4=>Edit::Pin(id,value!=0),5=>Edit::Quota(id,value),6=>Edit::Budget(id,value),7=>Edit::Cap(id,value),_=>return Err("operation".into())});
   }
   let result=ledger.transact(expected,&edits,&i.query()?);
   results.push(format!("{{\"accepted\":{},\"revision\":{},\"violations\":{},\"certificate\":{}}}",result.accepted,result.revision,result.violations.map(|x|array(&x)).unwrap_or_else(||"null".into()),certificate(result.certificate)));
  }
  output.push(format!("{{\"nodes\":{},\"templates\":{},\"initial\":{},\"transactions\":[{}]}}",case.problem.num_nodes,case.problem.demands.len(),initial,results.join(",")));
 }
 if i.at!=i.words.len(){return Err("extra".into());}
 Ok(format!("{{\"sessions\":[{}]}}",output.join(",")))
}
fn main(){
 let mut raw=String::new();io::stdin().read_to_string(&mut raw).unwrap();
 let mut i=Input{words:raw.split_whitespace().map(str::to_string).collect(),at:0};
 match run(&mut i){Ok(out)=>println!("{}",out),Err(_)=>println!("{{\"error\":\"invalid\"}}")}
}
