    for a in range(K):
        if up[a][a] != 0 or pr[a][a] is not None:
            return False
    for a in range(K):
        row = up[a]
        for x, y, low, high in meas:
            d = row[x] - row[y]
            if d < low or d > high:
                return False
    src, dst, w = para.constraint_arrays(meas)
    sl = src.tolist(); dl = dst.tolist(); wl = w.tolist()
    M2 = len(sl)
    for a in range(K):
        for b in range(K):
            if b == a:
                continue
            cur = b
            total = 0
            steps = 0
            while cur != a:
                c = pr[a][cur]
                if not _is_int(c) or c < 0 or c >= M2:
                    return False
                if dl[c] != cur:
                    return False
                total += wl[c]
                cur = sl[c]
                steps += 1
                if steps > K:
                    return False
            if total != up[a][b]:
                return False
    return True


def _flat_matrix(mat, P, N):
    """Flatten a P x N artifact matrix; returns None on a shape defect."""
    if not isinstance(mat, list) or len(mat) != P:
        return None
    out = [None] * (P * N)
    for p in range(P):
        row = mat[p]
        if not isinstance(row, list) or len(row) != N:
            return None
        base = p * N
        for i in range(N):
            out[base + i] = row[i]
    return out


