                                m = d % R.T
                                L = rr + (1 if m else 0)
                                if any(x % P in R.bl[l] for x in range(pu, pu + L)):
                                    continue
                                if L + q != adv:
                                    continue
                                kind = 2 * l + dirn
                        if kind is None:
