        errors.append(f'{path}: rules not sorted by (length, ids)')
    active = result.get('active', [])
    if not isinstance(active, list):
        errors.append(f'{path}: active not a list')
    else:
        for i, clause in enumerate(active):
            if not (isinstance(clause, list) and all(isinstance(x, int) and not isinstance(x, bool) for x in clause)):
                errors.append(f'{path}: active {i} types {clause}')
            elif tuple(clause) not in clauses:
                errors.append(f'{path}: active {i} is not a discovered rule {clause}')
        expected = [list(c) for c in clauses if list(c) in [list(a) for a in active]]
        if [tuple(a) for a in active] != [c for c in clauses if list(c) in [list(a) for a in active]]:
            errors.append(f'{path}: active not in rule order')
    approved = {tuple(a) for a in job['approved']}
    for a in active:
        if tuple(a) not in approved:
            errors.append(f'{path}: active clause {a} was never approved')
    answers = result.get('answers', [])
    if len(answers) != len(job['queries']):
        errors.append(f'{path}: answer count {len(answers)} vs queries {len(job["queries"])}')
    for i, ans in enumerate(answers):
        if set(ans) != {'count', 'tokens', 'witness'}:
            errors.append(f'{path}: answer {i} keys {sorted(ans)}')
            continue
        count = ans['count']
        tokens = ans['tokens']
        witness = ans['witness']
        if not (isinstance(count, int) and not isinstance(count, bool) and 0 <= count <= U):
            errors.append(f'{path}: answer {i} count {count}')
        if not isinstance(tokens, list):
            errors.append(f'{path}: answer {i} tokens not a list')
        else:
            if any(t not in DIGIT_TOKENS for t in tokens):
                errors.append(f'{path}: answer {i} bad token {tokens}')
            if tokens != [t for t in DIGIT_TOKENS if t in tokens]:
                errors.append(f'{path}: answer {i} token order {tokens}')
            if len(set(tokens)) != len(tokens):
                errors.append(f'{path}: answer {i} duplicate tokens {tokens}')
        if witness is not None and not (isinstance(witness, int) and not isinstance(witness, bool)
                                        and 0 <= witness < U):
            errors.append(f'{path}: answer {i} witness {witness}')
        if count == 0 and (tokens or witness is not None):
            errors.append(f'{path}: answer {i} empty completion but tokens {tokens} witness {witness}')
        if count > 0 and not tokens:
            errors.append(f'{path}: answer {i} nonempty completion without tokens')
    return errors
