                if r < 0.8 and depth == 0:
                    n = rng.randint(1, 3)
                    refs = []
                    seen = set()
                    for _ in range(n):
                        ref = rand_ref()
                        k = tuple(ref)
                        while k in seen:
                            ref = rand_ref(); k = tuple(ref)
                        seen.add(k)
                        refs.append(ref)
