def ref_replay(req):
    caps = req['capacities']
    flows = {f['id']: f for f in req['flows']}
    # label per node
    tables = {}  # (node,label) -> fid
    enabled = set()
    results = []
    for ev in req['events']:
        op = ev['op']
        if op == 'put':
            f = flows[ev['flow']]; node = ev['node']
            lab = f['labels'][f['path'].index(node)]
            key = (node, lab)
            if tables.get(key) == f['id']:
                results.append({'status':'ok'})
            elif key in tables and tables[key] in enabled:
                results.append({'status':'busy'})
            elif key not in tables and sum(1 for (n,l) in tables if n==node) >= caps[node]:
                results.append({'status':'full'})
            else:
                tables[key] = f['id']
                results.append({'status':'ok'})
        elif op == 'enable':
            f = flows[ev['flow']]
            if all(tables.get((n, f['labels'][i])) == f['id'] for i,n in enumerate(f['path'])):
                enabled.add(f['id']); results.append({'status':'ok'})
            else:
                results.append({'status':'unready'})
        elif op == 'disable':
            enabled.discard(ev['flow']); results.append({'status':'ok'})
        elif op == 'reset':
            enabled.clear(); results.append({'status':'ok'})
        else:
            f = flows[ev['flow']]
            h = bytes.fromhex(ev['header']); pl = bytes.fromhex(ev['payload'])
            kinds = f['kinds']; tpl = bytes.fromhex(f['template'])
            N = len(f['path'])
            if f['id'] not in enabled: mode, reason = 'ip','disabled'
            elif any(h[i]!=tpl[i] for i,c in enumerate(kinds) if c=='K'): mode,reason='ip','mismatch'
            elif h[kinds.index('Q')]>7: mode,reason='ip','qos'
            else: mode,reason='mpls','compressed'
            t = h[kinds.index('T')]
            wire=[]
            for i in range(N):
                if t <= i: break
                if mode=='mpls':
                    lab = f['labels'][i]; q=h[kinds.index('Q')]
                    val = (lab<<12)|(q<<9)|(1<<8)|(t-i)
                    res = bytes(h[i] for i,c in enumerate(kinds) if c=='D')
                    wire.append((val.to_bytes(4,'big')+res+pl).hex())
                else:
                    hh = bytearray(h); hh[kinds.index('T')] = t-i
                    wire.append((bytes(hh)+pl).hex())
            if len(wire)==N:
                if mode=='mpls':
                    out = bytearray(tpl)
                    res = bytes(h[i] for i,c in enumerate(kinds) if c=='D')
                    di=0
                    for i,c in enumerate(kinds):
                        if c=='D': out[i]=res[di]; di+=1
                        elif c=='Z': out[i]=0
                        elif c=='Q': out[i]=h[kinds.index('Q')]
                        elif c=='T': out[i]=t-(N-1)
                    delivered=(bytes(out)+pl).hex()
                else:
                    delivered=wire[-1]
            else:
                delivered=None
            results.append({'mode':mode,'reason':reason,'wire':wire,'delivered':delivered,
                            'byte_hops':sum(len(bytes.fromhex(w)) for w in wire)})
    tables_out=[{'node':n,'label':l,'flow':fl} for (n,l),fl in sorted(tables.items())]
    return {'results':results,'active':sorted(enabled),'tables':tables_out}
