use std::io::{self, Read};
use rust_unit_merge::ledger::{Task,Edit,Query,Certificate,Ledger,template_domains};
use rust_unit_merge::topology::*;

struct Input { words:Vec<String>, at:usize }
impl Input {
 fn next(&mut self)->Result<String,String> {if self.at>=self.words.len(){return Err("truncated".into());}let s=self.words[self.at].clone();self.at+=1;Ok(s)}
 fn n(&mut self)->Result<usize,String>{self.next()?.parse().map_err(|_|"integer".into())}
 fn u(&mut self)->Result<u64,String>{self.next()?.parse().map_err(|_|"integer".into())}
 fn ids(&mut self)->Result<Vec<usize>,String>{let n=self.n()?;(0..n).map(|_|self.n()).collect()}
 fn query(&mut self)->Result<Query,String>{Ok(Query{groups:self.ids()?,nodes:self.ids()?,tasks:self.ids()?})}
}
fn topology(i:&mut Input)->Result<(TopologyCase,usize,Vec<usize>),String>{
 let code=i.n()?; let args=(0..7).map(|_|i.n()).collect::<Result<Vec<_>,_>>()?;
 let picked=match code {
  0=>build_clos(args[0],1,None,None,args[2]!=0,if args[1]==0 {ClosSourceGroupScope::Tor}else{ClosSourceGroupScope::Pod}),
  1=>build_leaf_spine(args[0],args[1],1),
  2=>build_torus2d(args[0],1,if args[1]==0 {Torus2DSourceGroupScope::Host}else{Torus2DSourceGroupScope::Row}),
  3=>build_torus3d(args[0],1,if args[1]==0 {Torus3DSourceGroupScope::Host}else{Torus3DSourceGroupScope::Line}),
  4=>build_dragonfly(args[0],args[1],args[2],Some(1),1.0,1,0,match args[3]{0=>DragonflySourceGroupScope::Router,1=>DragonflySourceGroupScope::Group,_=>DragonflySourceGroupScope::SourceTargetGroup}),
  5=>build_dragonfly_plus(args[0],args[1],args[2],args[3],args[4]!=0,1,0,if args[5]==0{DragonflyPlusSourceGroupScope::Tor}else{DragonflyPlusSourceGroupScope::Group}),
  _=>return Err("topology".into()),
 };
 Ok((picked,code,args))
}
fn array<T:std::fmt::Display>(row:&[T])->String{format!("[{}]",row.iter().map(|x|x.to_string()).collect::<Vec<_>>().join(","))}
fn rows<T:std::fmt::Display,const N:usize>(data:&[[T;N]])->String{format!("[{}]",data.iter().map(|x|array(x)).collect::<Vec<_>>().join(","))}
fn certificate(c:Certificate)->String{format!("{{\"totals\":{},\"groups\":{},\"nodes\":{},\"tasks\":{}}}",array(&c.totals),rows(&c.groups),rows(&c.nodes),rows(&c.tasks))}
fn run(i:&mut Input)->Result<String,String>{
 let sessions=i.n()?;let mut output=Vec::new();
 for _ in 0..sessions {
  let (case,code,args)=topology(i)?;let task_count=i.n()?;let group_count=i.n()?;
  let caps=(0..case.problem.num_nodes).map(|_|i.u()).collect::<Result<Vec<_>,_>>()?;
  let mut quotas=Vec::new();let mut budgets=Vec::new();
  for _ in 0..group_count{quotas.push(i.u()?);budgets.push(i.u()?);}
  let mut tasks=Vec::new();
  for _ in 0..task_count{tasks.push(Task{template:i.n()?,group:i.n()?,weight:i.u()?,class:i.u()?,pinned:i.n()?!=0});}
  let domains=template_domains(code,&args,&case.problem);
  let mut ledger=Ledger::new(&case.problem,domains,tasks,quotas,budgets,caps)?;
  let initial=certificate(ledger.certificate(&i.query()?));
  let transactions=i.n()?;let mut results=Vec::new();
  for _ in 0..transactions{
   let expected=i.u()?;let operations=i.n()?;let mut edits=Vec::new();
   for _ in 0..operations{
    let op=i.n()?;let id=i.n()?;let value=i.u()?;
    edits.push(match op{0=>Edit::Move(id,value as usize),1=>Edit::Weight(id,value),2=>Edit::Class(id,value),3=>Edit::Bind(id,value as usize),4=>Edit::Pin(id,value!=0),5=>Edit::Quota(id,value),6=>Edit::Budget(id,value),7=>Edit::Cap(id,value),_=>return Err("operation".into())});
   }
   let result=ledger.transact(expected,&edits,&i.query()?);
   results.push(format!("{{\"accepted\":{},\"revision\":{},\"violations\":{},\"certificate\":{}}}",result.accepted,result.revision,result.violations.map(|x|array(&x)).unwrap_or_else(||"null".into()),certificate(result.certificate)));
  }
  output.push(format!("{{\"nodes\":{},\"templates\":{},\"initial\":{},\"transactions\":[{}]}}",case.problem.num_nodes,case.problem.demands.len(),initial,results.join(",")));
 }
 if i.at!=i.words.len(){return Err("extra".into());}
 Ok(format!("{{\"sessions\":[{}]}}",output.join(",")))
}
fn main(){
 let mut raw=String::new();io::stdin().read_to_string(&mut raw).unwrap();
 let mut i=Input{words:raw.split_whitespace().map(str::to_string).collect(),at:0};
 match run(&mut i){Ok(out)=>println!("{}",out),Err(_)=>println!("{{\"error\":\"invalid\"}}")}
}

//! Transactional certificate layer for weighted cache-group reconfigurations.
//!
//! The ledger keeps the committed configuration and certifies proposals built
//! from ordered field assignments.  Committed state is never destroyed by a
//! rejected proposal: every speculative mutation is recorded in a journal of
//! inverse operations which is replayed backwards on rejection.  All validity
//! decisions (node capacity, group homogeneity, weighted work budgets and pin
//! protection) are computed exactly on the final proposal.

use crate::solver::SolverProblem;
use std::collections::HashMap;

/// One service task bound to a template and a cache group.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Task {
    pub template: usize,
    pub group: usize,
    pub weight: u64,
    pub class: u64,
    pub pinned: bool,
}

#[derive(Clone, Debug)]
pub enum Edit {
    Move(usize, usize), Weight(usize, u64), Class(usize, u64), Bind(usize, usize),
    Pin(usize, bool), Quota(usize, u64), Budget(usize, u64), Cap(usize, u64),
}

#[derive(Clone, Default)]
pub struct Query { pub groups: Vec<usize>, pub nodes: Vec<usize>, pub tasks: Vec<usize> }

pub struct Certificate {
    pub totals: [u64; 4],
    pub groups: Vec<[i64; 8]>,
    pub nodes: Vec<[u64; 3]>,
    pub tasks: Vec<[u64; 6]>,
}

pub struct Outcome {
    pub accepted: bool,
    pub revision: u64,
    pub violations: Option<[u64; 4]>,
    pub certificate: Certificate,
}

/// Domain of every template, derived from the topology scope of the session.
///
/// `code`/`args` are the encoded topology descriptor produced by the transport
/// layer; endpoint pairs come from the routing templates themselves.
pub fn template_domains(code: usize, args: &[usize], problem: &SolverProblem) -> Vec<i64> {
    let mut out = Vec::with_capacity(problem.demands.len());
    for demand in &problem.demands {
        let src = demand.src as i64;
        let dst = demand.dst as i64;
        let value = match code {
            // clos: args = [k, pod-scope, intra]
            0 => if args[1] != 0 { src / (args[0] as i64 / 2) } else { src },
            // leaf-spine
            1 => src,
            // torus2d / torus3d: args = [n, row/line scope]
            2 | 3 => if args[1] != 0 { src / args[0] as i64 } else { src },
            // dragonfly: args = [g, a, h, 0=router 1=group 2=target]
            4 => match args[3] {
                1 => src / args[1] as i64,
                2 => src * args[0] as i64 + dst / args[1] as i64,
                _ => src,
            },
            // dragonfly-plus: args = [g, l, s, h, dense, group-scope]
            5 => {
                let span = (args[1] + args[2]) as i64;
                let leaves = args[1] as i64;
                if args[5] != 0 { src / span } else { (src / span) * leaves + src % span }
            }
            _ => src,
        };
        out.push(value);
    }
    out
}

/// Journal entry: enough information to mirror one committed mutation.
#[derive(Clone, Copy, Debug)]
enum Undo {
    Move(usize, usize),
    Bind(usize, usize),
    Weight(usize, u64),
    Class(usize, u64),
    Pin(usize, bool),
    Quota(usize, u64),
    Budget(usize, u64),
    Cap(usize, u64),
}

/// Start-of-transaction snapshot of a touched service task.
struct TaskSnap {
    id: usize,
    group: usize,
    template: usize,
    weight: u64,
    class: u64,
    pinned: bool,
}

/// Start-of-transaction snapshot of a group touched by a quota assignment.
struct GroupSnap {
    id: usize,
    quota: u64,
    pins: i64,
}

pub struct Ledger {
    num_nodes: usize,
    words: usize,
    /// Cache-bearing footprint of every routing template, as a bit set.
    template_fp: Vec<u64>,
    /// Cache domain of every routing template.
    dom: Vec<i64>,

    task: Vec<Task>,
