/* Offline four-port EPIC collective collector.
 *
 * Finite CPU packet replay: no live transport, no timers, no hardware. The
 * collector consumes canonical RoCE frames on four ingress ports, keeps the
 * bounded retention window required by PROTOCOL.md, emits canonical egress
 * frames through an in-memory transcript and returns wire/buffer certificates.
 */

#define _DEFAULT_SOURCE

#include "epic_clean.h"
#include "offline_api.h"

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define M24 0x00ffffffu
#define MAX_FRAME EPIC_MAX_FRAME_BYTES

/* ============================== SHA-256 ============================== */

typedef struct { uint32_t h[8]; uint64_t len; uint32_t fill; uint8_t buf[64]; } sha_t;

static const uint32_t sha_k[64] = {
    0x428a2f98u, 0x71374491u, 0xb5c0fbcfu, 0xe9b5dba5u, 0x3956c25bu, 0x59f111f1u,
    0x923f82a4u, 0xab1c5ed5u, 0xd807aa98u, 0x12835b01u, 0x243185beu, 0x550c7dc3u,
    0x72be5d74u, 0x80deb1feu, 0x9bdc06a7u, 0xc19bf174u, 0xe49b69c1u, 0xefbe4786u,
    0x0fc19dc6u, 0x240ca1ccu, 0x2de92c6fu, 0x4a7484aau, 0x5cb0a9dcu, 0x76f988dau,
    0x983e5152u, 0xa831c66du, 0xb00327c8u, 0xbf597fc7u, 0xc6e00bf3u, 0xd5a79147u,
    0x06ca6351u, 0x14292967u, 0x27b70a85u, 0x2e1b2138u, 0x4d2c6dfcu, 0x53380d13u,
    0x650a7354u, 0x766a0abbu, 0x81c2c92eu, 0x92722c85u, 0xa2bfe8a1u, 0xa81a664bu,
    0xc24b8b70u, 0xc76c51a3u, 0xd192e819u, 0xd6990624u, 0xf40e3585u, 0x106aa070u,
    0x19a4c116u, 0x1e376c08u, 0x2748774cu, 0x34b0bcb5u, 0x391c0cb3u, 0x4ed8aa4au,
    0x5b9cca4fu, 0x682e6ff3u, 0x748f82eeu, 0x78a5636fu, 0x84c87814u, 0x8cc70208u,
    0x90befffau, 0xa4506cebu, 0xbef9a3f7u, 0xc67178f2u};

#define ROTR(x, n) (((x) >> (n)) | ((x) << (32 - (n))))

static void sha_block(uint32_t *h, const uint8_t *p) {
    uint32_t w[64];
    for (int i = 0; i < 16; i++) {
        w[i] = ((uint32_t)p[4 * i] << 24) | ((uint32_t)p[4 * i + 1] << 16) |
               ((uint32_t)p[4 * i + 2] << 8) | (uint32_t)p[4 * i + 3];
    }
    for (int i = 16; i < 64; i++) {
        uint32_t a = w[i - 15], b = w[i - 2];
        uint32_t s0 = ROTR(a, 7) ^ ROTR(a, 18) ^ (a >> 3);
        uint32_t s1 = ROTR(b, 17) ^ ROTR(b, 19) ^ (b >> 10);
        w[i] = w[i - 16] + s0 + w[i - 7] + s1;
    }
    uint32_t a = h[0], b = h[1], c = h[2], d = h[3], e = h[4], f = h[5], g = h[6], hh = h[7];
    for (int i = 0; i < 64; i++) {
        uint32_t s1 = ROTR(e, 6) ^ ROTR(e, 11) ^ ROTR(e, 25);
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t t1 = hh + s1 + ch + sha_k[i] + w[i];
        uint32_t s0 = ROTR(a, 2) ^ ROTR(a, 13) ^ ROTR(a, 22);
        uint32_t mj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = s0 + mj;
        hh = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + t2;
    }
    h[0] += a; h[1] += b; h[2] += c; h[3] += d;
    h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
}

static void sha_init(sha_t *s) {
    static const uint32_t iv[8] = {0x6a09e667u, 0xbb67ae85u, 0x3c6ef372u, 0xa54ff53au,
                                   0x510e527fu, 0x9b05688cu, 0x1f83d9abu, 0x5be0cd19u};
    memcpy(s->h, iv, sizeof(iv));
    s->len = 0;
    s->fill = 0;
}

static void sha_update(sha_t *s, const void *data, size_t n) {
    const uint8_t *p = (const uint8_t *)data;
    s->len += (uint64_t)n;
    if (s->fill) {
        while (n && s->fill < 64) {
            s->buf[s->fill++] = *p++;
            n--;
        }
        if (s->fill == 64) {
            sha_block(s->h, s->buf);
            s->fill = 0;
        }
    }
    while (n >= 64) {
        sha_block(s->h, p);
        p += 64;
        n -= 64;
    }
    while (n) {
        s->buf[s->fill++] = *p++;
        n--;
    }
}

static void sha_final(const sha_t *s, uint8_t out[32]) {
    sha_t t = *s;
    uint64_t bits = t.len << 3;
    uint8_t one = 0x80, zero = 0, lb[8];
    sha_update(&t, &one, 1);
    while (t.fill != 56) {
        sha_update(&t, &zero, 1);
    }
    for (int i = 0; i < 8; i++) {
        lb[i] = (uint8_t)(bits >> (56 - 8 * i));
    }
    sha_update(&t, lb, 8);
    for (int i = 0; i < 8; i++) {
        out[4 * i] = (uint8_t)(t.h[i] >> 24);
        out[4 * i + 1] = (uint8_t)(t.h[i] >> 16);
        out[4 * i + 2] = (uint8_t)(t.h[i] >> 8);
        out[4 * i + 3] = (uint8_t)t.h[i];
    }
}

/* ============================ collector core ============================ */

enum { P_ALLREDUCE = 0, P_REDUCE = 1, P_BCAST = 2, P_BARRIER = 3, P_ALLGATHER = 4, P_RSCATTER = 5 };
enum { MODE_RELAY = 2, MODE_OWN = 3 };

typedef struct {
    uint32_t p;
    uint8_t in_use, mask, complete;
    uint8_t *g[4];
} slot_t;

typedef struct {
    bool is_data, is_ack;
    uint32_t psn;
    uint32_t p;
    const uint8_t *payload;
} rx_info_t;

typedef struct {
    uint64_t state[32];
    uint64_t buffer;
    uint8_t sha[32];
    uint64_t packets, bytes;
    uint32_t snap_count, trace_count;
    const epic_snap_t *snaps;
    const epic_trace_t *trace;
} collector_result_t;

struct collector {
    int primitive, mode, root;
    uint32_t K, D, N, start, quarter, need_mask;
    size_t plen, stride;
    uint8_t *pay;
    slot_t *slots;
    uint32_t b;
    uint32_t R[4], E[4], U[4], S[4], acked[4];
    uint8_t repeat[4];
    uint64_t occupied;
    uint64_t n_rx_data, n_rx_ack, n_tx_data, n_tx_ack;
    uint64_t n_accepted, n_dup, n_blocked, n_stale;
    uint64_t n_wire, n_endpoint, n_ack_ignored, n_failed, n_overwrite;
    int64_t budget;
    sha_t sha;
    uint64_t packets, bytes;
    uint32_t trace_limit, trace_count;
    epic_trace_t *trace;
    epic_snap_t *snaps;
    uint32_t snap_count, snap_cap;
    collector_result_t res;
    uint8_t out[MAX_FRAME];
    uint8_t inb[MAX_FRAME];
    uint8_t mac_host[4][6], mac_sw[4][6];
    uint32_t ip_host[4], ip_sw[4];
};

typedef struct collector collector_t;

static int rank_of_ordinal(int dest, int ordinal) {
    for (int r = 0; r < 4; r++) {
        if (r == dest) {
            continue;
        }
        if (ordinal == 0) {
            return r;
        }
        ordinal--;
    }
    return 0;
}

static int ordinal_of(int dest, int src) {
    int ordinal = 0;
    for (int r = 0; r < 4; r++) {
        if (r == dest) {
            continue;
        }
        if (r == src) {
            return ordinal;
        }
        ordinal++;
    }
    return 0;
}

static bool is_source(const collector_t *c, int rank) {
    return c->primitive != P_BCAST || rank == c->root;
}

static uint32_t out_limit(const collector_t *c, int d) {
    switch (c->primitive) {
    case P_ALLREDUCE:
        return c->K;
    case P_REDUCE:
        return d == c->root ? c->K : 0;
    case P_BCAST:
        return d == c->root ? 0 : c->K;
    case P_BARRIER:
        return 1;
    case P_ALLGATHER:
        return 3u * c->K;
    case P_RSCATTER:
        return c->quarter;
    }
    return 0;
}

/* Map a destination output position q to its input p and payload source. */
static bool output_map(const collector_t *c, int d, uint32_t q, uint32_t *pp, int *srcp) {
    uint32_t p = 0;
    int src = -1;
    switch (c->primitive) {
    case P_ALLREDUCE:
        p = q;
        break;
    case P_REDUCE:
        if (d != c->root) {
            return false;
        }
        p = q;
        break;
    case P_BCAST:
        if (d == c->root) {
            return false;
        }
        p = q;
        break;
    case P_BARRIER:
        if (q != 0) {
            return false;
        }
        p = 0;
        break;
    case P_ALLGATHER:
        p = q / 3u;
        src = rank_of_ordinal(d, (int)(q % 3u));
        break;
    case P_RSCATTER:
        p = (uint32_t)d * c->quarter + q;
        break;
    default:
        return false;
    }
    if (p >= c->K) {
        return false;
    }
    *pp = p;
    *srcp = src;
    return true;
}

static slot_t *slot_of(const collector_t *c, uint32_t p) {
    slot_t *s = &c->slots[p % c->N];
    if (!s->in_use || s->p != p) {
        return NULL;
    }
    return s;
}

static bool output_ready(collector_t *c, int d, uint32_t q) {
    uint32_t p;
    int src;
    if (!output_map(c, d, q, &p, &src)) {
        return false;
    }
    slot_t *s = slot_of(c, p);
    return s && s->complete;
}

static uint8_t *slot_payload(collector_t *c, uint32_t p) {
    return c->pay + (size_t)(p % c->N) * c->stride;
}

/* ------------------------------ transcript ------------------------------ */

static bool emit_frame(collector_t *c, int rank, const uint8_t *frame, size_t len, bool ack) {
    if (c->budget == 0) {
        c->n_failed++;
        return false;
    }
    if (c->budget > 0) {
        c->budget--;
    }
    uint8_t head[5];
    head[0] = (uint8_t)rank;
    head[1] = (uint8_t)(len & 0xffu);
    head[2] = (uint8_t)((len >> 8) & 0xffu);
    head[3] = (uint8_t)((len >> 16) & 0xffu);
    head[4] = (uint8_t)((len >> 24) & 0xffu);
    sha_update(&c->sha, head, 5);
    sha_update(&c->sha, frame, len);
    c->packets++;
    c->bytes += (uint64_t)len;
    if (ack) {
        c->n_tx_ack++;
    } else {
        c->n_tx_data++;
    }
    if (c->trace_count < c->trace_limit) {
        epic_trace_t *t = &c->trace[c->trace_count++];
        t->len = (uint32_t)len;
        t->rank = (uint8_t)rank;
        memcpy(t->frame, frame, len);
    }
    return true;
}

static bool send_ack_to(collector_t *c, int rank, uint32_t prefix) {
    const epic_port_t dummy;
    (void)dummy;
    size_t len = epic_build_roce_ack(c->out, sizeof(c->out), c->mac_sw[rank], c->mac_host[rank],
                                     c->ip_sw[rank], c->ip_host[rank], EPIC_ROCE_UDP_PORT,
                                     EPIC_ROCE_UDP_PORT, 0x100u + (uint32_t)rank,
                                     (c->start + prefix - 1u) & M24);
    if (!len) {
        return false;
    }
    return emit_frame(c, rank, c->out, len, true);
}

static bool send_output(collector_t *c, int d, uint32_t q) {
    uint32_t p;
    int src;
    if (!output_map(c, d, q, &p, &src)) {
        return false;
    }
    slot_t *s = slot_of(c, p);
    if (!s) {
        return false;
    }
    uint32_t psn = (c->start + q) & M24;
    size_t len;
    if (c->primitive == P_ALLGATHER) {
        if (!s->g[src]) {
            return false;
        }
        len = epic_build_roce_data_raw(c->out, sizeof(c->out), c->mac_sw[d], c->mac_host[d],
                                       c->ip_sw[d], c->ip_host[d], EPIC_ROCE_UDP_PORT,
                                       EPIC_ROCE_UDP_PORT, 0x100u + (uint32_t)d, psn, s->g[src],
                                       c->plen);
    } else if (c->primitive == P_BCAST) {
        len = epic_build_roce_data_raw(c->out, sizeof(c->out), c->mac_sw[d], c->mac_host[d],
                                       c->ip_sw[d], c->ip_host[d], EPIC_ROCE_UDP_PORT,
                                       EPIC_ROCE_UDP_PORT, 0x100u + (uint32_t)d, psn,
                                       slot_payload(c, p), c->plen);
    } else {
        len = epic_build_roce_data(c->out, sizeof(c->out), c->mac_sw[d], c->mac_host[d],
                                   c->ip_sw[d], c->ip_host[d], EPIC_ROCE_UDP_PORT,
                                   EPIC_ROCE_UDP_PORT, 0x100u + (uint32_t)d, psn,
                                   (const int32_t *)slot_payload(c, p), c->plen);
    }
    if (!len) {
        return false;
    }
    return emit_frame(c, d, c->out, len, false);
}

/* ------------------------- eligibility and safety ------------------------- */

static bool contribution_safe(const collector_t *c, int r, uint32_t p) {
    if (c->mode == MODE_OWN) {
        return true;
    }
    switch (c->primitive) {
    case P_ALLREDUCE:
    case P_BARRIER:
        return c->acked[r] > p;
    case P_REDUCE:
        return c->acked[c->root] > p;
    case P_BCAST:
        for (int d = 0; d < 4; d++) {
            if (d == c->root) {
                continue;
            }
            if (c->acked[d] <= p) {
                return false;
            }
        }
        return true;
    case P_RSCATTER:
        return c->acked[p / c->quarter] > p % c->quarter;
    case P_ALLGATHER:
        for (int d = 0; d < 4; d++) {
            if (d == r) {
                continue;
            }
            if (c->acked[d] <= 3u * p + (uint32_t)ordinal_of(d, r)) {
                return false;
            }
        }
        return true;
    }
    return false;
}

static void extend_eligible(collector_t *c, int r) {
    if (c->mode == MODE_OWN) {
        c->E[r] = c->R[r];
        return;
    }
    while (c->E[r] < c->R[r] && contribution_safe(c, r, c->E[r])) {
        c->E[r]++;
    }
}

static bool outputs_acked(const collector_t *c, uint32_t p) {
    switch (c->primitive) {
    case P_ALLREDUCE:
        for (int d = 0; d < 4; d++) {
            if (c->acked[d] <= p) {
                return false;
            }
        }
        return true;
    case P_REDUCE:
        return c->acked[c->root] > p;
    case P_BCAST:
        for (int d = 0; d < 4; d++) {
            if (d == c->root) {
                continue;
            }
            if (c->acked[d] <= p) {
                return false;
            }
        }
        return true;
    case P_BARRIER:
        for (int d = 0; d < 4; d++) {
            if (c->acked[d] < 1u) {
                return false;
            }
        }
        return true;
    case P_ALLGATHER:
        for (int d = 0; d < 4; d++) {
            if (c->acked[d] < 3u * p + 3u) {
                return false;
            }
        }
        return true;
    case P_RSCATTER:
        return c->acked[p / c->quarter] > p % c->quarter;
    }
    return false;
}

static bool upstream_sent(const collector_t *c, uint32_t p) {
    for (int r = 0; r < 4; r++) {
        if (!is_source(c, r)) {
            continue;
        }
        if (c->U[r] <= p) {
            return false;
        }
    }
    return true;
}

static void free_slot(collector_t *c, slot_t *s) {
    for (int r = 0; r < 4; r++) {
        free(s->g[r]);
        s->g[r] = NULL;
    }
    if (s->in_use) {
        c->occupied--;
    }
    memset(s, 0, sizeof(*s));
    s->p = 0;
    s->in_use = 0;
}

static void retire(collector_t *c) {
    for (;;) {
        if (c->b >= c->K) {
            return;
        }
        uint32_t p = c->b;
        slot_t *s = slot_of(c, p);
        if (!s || !s->complete) {
            return;
        }
        if (!outputs_acked(c, p) || !upstream_sent(c, p)) {
            return;
        }
        free_slot(c, s);
        c->b++;
    }
}

/* ------------------------------- service ------------------------------- */

static void service(collector_t *c, bool is_retry, int retry_rank) {
    for (int r = 0; r < 4; r++) {
        extend_eligible(c, r);
    }

    /* 1. eligible pending upstream ACKs, ascending rank */
    for (int r = 0; r < 4; r++) {
        if (c->E[r] == 0 || (!c->repeat[r] && c->E[r] <= c->U[r])) {
            continue;
        }
        if (!send_ack_to(c, r, c->E[r])) {
            retire(c);
            return;
        }
        c->U[r] = c->E[r];
        c->repeat[r] = 0;
    }

    /* 2. on retry only: the selected receiver's sent but unacknowledged results */
    if (is_retry) {
        uint32_t q = c->acked[retry_rank];
        while (q < c->S[retry_rank]) {
            if (!output_ready(c, retry_rank, q)) {
                break;
            }
            if (!send_output(c, retry_rank, q)) {
                retire(c);
                return;
            }
            q++;
        }
    }

    /* 3. new results, ascending destination rank then q */
    for (int d = 0; d < 4; d++) {
        while (c->S[d] < out_limit(c, d)) {
            if (!output_ready(c, d, c->S[d])) {
                break;
            }
            if (!send_output(c, d, c->S[d])) {
                retire(c);
                return;
            }
            c->S[d]++;
        }
    }
    retire(c);
}

/* --------------------------- wire classification --------------------------- */

static bool wire_valid(const collector_t *c, const uint8_t *f, size_t len, rx_info_t *info) {
    if (len < 58u) {
        return false;
    }
    if (f[12] != 0x08 || f[13] != 0x00) {
        return false;
    }
    const uint8_t *ip = f + 14;
    size_t ip_len = ((size_t)ip[2] << 8) | (size_t)ip[3];
    if (ip_len + 14u != len) {
        return false;
    }
    if (ip[0] != 0x45) {
        return false;
    }
    if (ip[9] != 17) {
        return false;
    }
    uint32_t sum = 0;
    for (int i = 0; i < 20; i += 2) {
        sum += ((uint32_t)ip[i] << 8) | (uint32_t)ip[i + 1];
    }
    while (sum >> 16) {
        sum = (sum & 0xffffu) + (sum >> 16);
    }
    if ((sum & 0xffffu) != 0xffffu) {
        return false;
    }
    uint32_t flags = ((uint32_t)ip[6] << 8) | (uint32_t)ip[7];
    if (flags != 0x0000u && flags != 0x4000u) {
        return false;
    }
    const uint8_t *udp = ip + 20;
