    running = 0
    for s in range(n):
        start[s] = running
        running += degree[s]
    start[n] = running
    rev = [0] * running
    pos = start[:]
    for s, row in enumerate(trans):
        for target in row:
            rev[pos[target]] = s
            pos[target] += 1
