class WindowSchema:
    """Field/column layout of one job plus its AST predicate definitions."""

    def __init__(self, job: dict[str, Any]):
        self.job = job
        self.order: list[str] = [field["name"] for field in job["fields"]]
        self.names: dict[str, int] = {name: index for index, name in enumerate(self.order)}
        self.types: dict[str, str] = {field["name"]: field["type"] for field in job["fields"]}
        self.field_domains: list[list[int]] = [list(field["domain"]) for field in job["fields"]]
        self.slots: int = int(job["slots"])
        self.nf: int = len(self.order)
        self.domains: list[list[int]] = [
            list(field["domain"]) for _ in range(self.slots) for field in job["fields"]
        ]
        self.columns: list[str] = [f"cell_{index}" for index in range(len(self.domains))]
        self.positions: dict[str, int] = {name: index for index, name in enumerate(self.columns)}
        self.families: dict[str, list[str]] = {
            field["name"]: [
                self.columns[self.position([slot, field["name"]])] for slot in range(self.slots)
            ]
            for field in job["fields"]
        }
        self.fields: dict[str, FieldSpec] = {
            self.columns[slot * self.nf + index]: FieldSpec(
                name=self.columns[slot * self.nf + index],
                value_type=ValueType.INTEGER,
                roles=[FieldRole(field["type"]) if field["type"] != "id" else FieldRole.IDENTIFIER],
                domain=list(field["domain"]),
                context_family=field["name"],
                context_index=slot,
            )
            for slot in range(self.slots)
            for index, field in enumerate(job["fields"])
        }
        self.spec = DatasetSpec(
            name="finite-windows",
            source=SourceSpec(type=SourceType.CSV),
            fields=list(self.fields.values()),
        )

    def position(self, ref: list[Any]) -> int:
        """Flattened cell index of a ``[slot, field_name]`` reference."""
        return ref[0] * self.nf + self.names[ref[1]]

    def term(self, term: dict[str, Any]) -> Any:
        """Translate a protocol term into the NetNomos term AST."""
        if "const" in term:
            return Constant(term["const"])
        if "sum" in term:
            return FuncCall("sum", tuple(SymbolRef(self.columns[self.position(ref)]) for ref in term["sum"]))
        ref = SymbolRef(self.columns[self.position(term["ref"])])
        return BinaryTerm("*", Constant(term["scale"]), ref) if "scale" in term else ref

    def predicates(self) -> list[GroundedPredicate]:
        """Grounded AST form of every input predicate, keeping input ids."""
        result: list[GroundedPredicate] = []
        for index, predicate in enumerate(self.job["predicates"]):
            op = Comparator(OPS[predicate["op"]])
            if predicate["kind"] == "cmp":
                formula: Formula = Compare(op.value, self.term(predicate["left"]), self.term(predicate["right"]))
                display = formula_to_string(formula)
            else:
                template = QuantifierTemplateSpec(
                    name="window",
                    quantifier="exists" if predicate["kind"] == "any" else "forall",
                    selector=VariableSelectorSpec(),
                    operators=[op],
                    constant=ConstantSelectorSpec(mode="explicit", values=[predicate["value"]]),
                )
                formula, display = project_quantified_family(
                    predicate["field"],
                    self.families[predicate["field"]],
                    template,
                    op,
                    SelectedConstant(predicate["value"], None),
                )
            result.append(
                GroundedPredicate(
                    str(index),
                    formula,
                    display,
                    0.0,
                    {"position": index, "kind": predicate["kind"]},
                )
            )

#!/usr/bin/env python3
"""Run the submitted CLI against public examples using actual bounded pipes."""
import json
import os
from pathlib import Path
import selectors
import signal
import subprocess
import sys
import time
HERE = Path(__file__).resolve().parent
sys.path.insert(0,str(HERE))
from runtime_limits import limit_child
ENV = {'PATH':'/usr/local/bin:/usr/bin:/bin','HOME':'/workspace',
       'LANG':'C','LC_ALL':'C','TMPDIR':'/workspace/tmp',
       'PYTHONDONTWRITEBYTECODE':'1','PYTHONUNBUFFERED':'1','PYTHONHASHSEED':'0',
       'OPENBLAS_NUM_THREADS':'1','OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1'}


def strict_json(data):
    def pairs(items):
        result = {}
        for k,v in items:
            if k in result:
                raise ValueError('duplicate key')
            result[k] = v
        return result
    def constant(value):
        raise ValueError('nonfinite number')
    return json.loads(data.decode('utf-8'), object_pairs_hook=pairs, parse_constant=constant)


def same(actual, expected):
    if type(actual) is not type(expected):
        return False
    if isinstance(expected, dict):
        return actual.keys() == expected.keys() and all(same(actual[k],v) for k,v in expected.items())
    if isinstance(expected, list):
        return len(actual) == len(expected) and all(same(a,b) for a,b in zip(actual,expected))
    return actual == expected


def run_candidate(candidate, data, *, timeout=60):
    if os.geteuid() == 0:
        raise RuntimeError('run this public check as a nonroot user in the public workspace')
    child = subprocess.Popen([sys.executable,'-I','-B',str(candidate)],
        stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
        env=ENV,close_fds=True,preexec_fn=limit_child)
    sel = selectors.DefaultSelector()
    streams = [child.stdin, child.stdout, child.stderr]
    buffers = [bytearray(),bytearray()]
    offset = 0
    deadline = time.monotonic()+timeout
    previous_handlers = {}
    def interrupted(signum, frame):
        raise InterruptedError('public check interrupted')
    for sig in (signal.SIGTERM,signal.SIGINT):
        previous_handlers[sig] = signal.signal(sig, interrupted)
    try:
        for stream in streams:
            os.set_blocking(stream.fileno(),False)
        if data:
            sel.register(child.stdin,selectors.EVENT_WRITE,-1)
        else:
            child.stdin.close()
        sel.register(child.stdout,selectors.EVENT_READ,0)
        sel.register(child.stderr,selectors.EVENT_READ,1)
        while sel.get_map():
            remaining = deadline-time.monotonic()
            if remaining <= 0:
                raise ValueError('candidate wall deadline exceeded')
            for key,_ in sel.select(min(.1,remaining)):
                stream,index = key.fileobj,key.data
                if index == -1:
                    try:
                        n = os.write(stream.fileno(),memoryview(data)[offset:offset+65536])
                    except BlockingIOError:
                        continue
                    except BrokenPipeError:
                        sel.unregister(stream);stream.close();continue
                    offset += n
                    if offset == len(data):
                        sel.unregister(stream);stream.close()
                else:
                    cap = (32*1024**2,1024**2)[index]
                    try:
                        block = os.read(stream.fileno(),min(65536,cap-len(buffers[index])+1))
                    except BlockingIOError:
                        continue
                    if not block:
                        sel.unregister(stream);stream.close()
                    elif len(buffers[index])+len(block) > cap:
                        raise ValueError(('stdout','stderr')[index]+' byte limit exceeded')
                    else:
                        buffers[index].extend(block)
        try:
            code = child.wait(timeout=max(.001,deadline-time.monotonic()))
        except subprocess.TimeoutExpired:
            raise ValueError('candidate wall deadline exceeded')
        if code != 0:
            raise ValueError('candidate exited nonzero')
        return bytes(buffers[0])
    finally:
        # No candidate descendants can be created after the child's seccomp setup.
        for sig in previous_handlers:
            signal.signal(sig,signal.SIG_IGN)
        if child.poll() is None:
            child.kill()
        child.wait()
        sel.close()
        for stream in streams:
            stream.close()
        for sig,handler in previous_handlers.items():
            signal.signal(sig,handler)


def main():
    if len(sys.argv) != 2:
        print('usage: python3 public_check.py PATH_TO_GATEWAY_PY',file=sys.stderr)
        return 2
    candidate = Path(sys.argv[1]).resolve()
    try:
        actual = strict_json(run_candidate(candidate,(HERE/'examples/batch.json').read_bytes()))
        expected = strict_json((HERE/'examples/expected.json').read_bytes())
        if not same(actual,expected):
            raise ValueError('public result mismatch')
    except (ValueError,OSError,RuntimeError,subprocess.SubprocessError,InterruptedError) as exc:
        print('FAIL: '+str(exc),file=sys.stderr)
        return 1
    print('PASS: public examples (sanity only)')
    return 0


if __name__ == '__main__':
    sys.exit(main())

