        nb = runs_b[ib + 1][0] if ib + 1 < len(runs_b) else U
        end = min(na, nb)
        o, n = runs_a[ia][1], runs_b[ib][1]
        if o != n:
            if out and out[-1][2] == o and out[-1][3] == n and out[-1][1] == pos:
                out[-1] = (out[-1][0], end, o, n)
            else:
                out.append((pos, end, o, n))
        if end == U:
            break
        if end == na:
            ia += 1
        if end == nb:
            ib += 1
        pos = end
    return out


WIDTH = (16, 8, 4)
LANES = (4, 8, 16)


def q_t(starts, bursts):
    R = len(starts)
    Q = [[0] * (R + 1) for _ in range(R + 1)]
    T = [[0] * (R + 1) for _ in range(R + 1)]
    for rep, cnt in bursts:
        for i in range(R):
            acc = 0
            for j in range(i + 1, R + 1):
                acc += cnt[j - 1]
                Q[i][j] += rep * acc
                if acc:
                    T[i][j] += rep
    return Q, T


class TooBig(Exception):
    pass


def brute(starts, bursts, C, hit, miss, dec, limit=400000):
    """Exhaustive layout enumeration for one version.
    Returns (options, byres) where options is the full list of
    (work, pages, resident, tree) and byres maps resident -> lex-min (work,pages)."""
    R = len(starts)
