    if outcome[0] == 'invalid':
        write(b'{"error":"invalid"}\n')
        out.flush()
        return
    write(b'{"results":[')
    first_job = True
    for valid, job in outcome[1]:
        if not first_job:
            write(b',')
        first_job = False
        if not valid:
            write(b'{"error":"invalid"}')
