        agent = Agent(job['services'], job['limits'])
        write(b'{"events":[')
        first_event = True
        for e in job['events']:
            if not first_event:
                write(b',')
            first_event = False
            write(json.dumps(agent.event(e), separators=(',', ':'),
                             ensure_ascii=True).encode('ascii'))
        write(b']}')
    write(b']}\n')
    out.flush()


