import random, subprocess, bisect, sys, time
from functools import lru_cache
WIDTH=[16,8,4]; LANES=[4,8,16]
def pages_for(span,b,mode):
    K=span if b==0 else b-1
    return (32+4*b+K*WIDTH[mode]+63)//64
def compositions(span):
    for b in range(2,min(9,span)+1):
        def rec(rem,k,p):
            if k==1: yield p+[rem]
            else:
                for x in range(1,rem-k+2): yield from rec(rem-x,k-1,p+[x])
        yield from rec(span,b,[])
def stats(starts,bursts):
    R=len(starts); Q=[[0]*(R+1) for _ in range(R+1)]; T=[[0]*(R+1) for _ in range(R+1)]; qrun=[0]*R
    for rep,addrs in bursts:
        touched=[0]*R
        for a in addrs:
            r=bisect.bisect_right(starts,a)-1; qrun[r]+=rep; touched[r]=1
        pref=[0]
        for x in touched: pref.append(pref[-1]+x)
        for i in range(R):
            for j in range(i+1,R+1):
                if pref[j]-pref[i]: T[i][j]+=rep
    pref=[0]
    for x in qrun: pref.append(pref[-1]+x)
    for i in range(R):
        for j in range(i+1,R+1): Q[i][j]=pref[j]-pref[i]
    return Q,T
def brute(starts,Q,T,cost,C):
    R=len(starts)
    @lru_cache(None)
    def sub(i,j):
        s=j-i; out=[]; qv=Q[i][j]; tv=T[i][j]; spread=starts[j-1]-starts[i]; legal=[0]
        if spread<1<<64: legal.append(1)
        if spread<1<<32: legal.append(2)
        if s<=8:
            for m in legal:
                P=pages_for(s,0,m); kw=(s+LANES[m]-1)//LANES[m]+cost[2][m]
                out.append((kw*qv+P*cost[1]*tv,P,0))
                if P<=C: out.append((kw*qv+P*cost[0]*tv,P,P))
        for comp in compositions(s):
            b=len(comp); combos=[(0,0,0)]; pos=i
            for x in comp:
                vv=sub(pos,pos+x)
                combos=[(w1+w2,p1+p2,c1+c2) for w1,p1,c1 in combos for w2,p2,c2 in vv if c1+c2<=C]
                pos+=x
            for ws,ps,cs in combos:
                for m in legal:
                    P=pages_for(s,b,m); kw=(b-1+LANES[m]-1)//LANES[m]+cost[2][m]; base=ws+kw*qv
                    out.append((base+P*cost[1]*tv,ps+P,cs))
