    inverse = []
    for symbol in sigma:
        table = {}
        for state, row in enumerate(trans):
            target = row.get(symbol)
            if target is not None:
                bucket = table.get(target)
                if bucket is None:
                    table[target] = [state]
                else:
                    bucket.append(state)
