def check_plan_witness(fab, g, bounds, ages, preds):
    N = fab.N
    P = fab.P
    wcost = fab.wcost
    is_anchor = fab.is_anchor
    step_info = fab.step_info
    for p in range(P):
        base = p * N
        prev_base = (p - 1) % P * N
        for i in range(N):
            v = base + i
            bv = bounds[v]
            if bv is None:
                if ages[v] is not None or preds[v] is not None:
                    return False
                continue
            av = ages[v]
            if not is_int(bv) or not is_int(av) or bv < 0 or av < 0:
                return False
            pr = preds[v]
            if is_anchor[v]:
                if pr is not None or bv != 0 or av != 0:
                    return False
                continue
            if not isinstance(pr, list) or len(pr) != 2:
                return False
            pv = pr[0]
            kind = pr[1]
            if not is_int(pv) or not is_int(kind):
                return False
            if pv < 0 or pv >= fab.V:
                return False
            bp = bounds[pv]
            ap = ages[pv]
            if bp is None or ap is None:
                return False
            if kind == -1:
                if pv != prev_base + i:
                    return False
                if bv != bp + wcost[pv] or av != ap + 1:
                    return False
            else:
                si = step_info(kind, pv // N, g)
                if si is None:
                    return False
                dv, cost, adel, src = si
                if dv != v or pv % N != src:
                    return False
                if bv != bp + cost or av != ap + adel:
                    return False
    return True


