# ------------------------------------------------------------- audit helpers

def _is_int(x):
    return type(x) is int


def check_cycle(cal, cyc):
    """Validate an inconsistency certificate (negative constraint cycle)."""
    if not isinstance(cyc, list):
        return False
    L = len(cyc)
    if L < 1 or L > cal.K:
        return False
    ids = []
    for x in cyc:
        if not _is_int(x):
            return False
        if x < 0 or x >= 2 * cal.m:
            return False
        ids.append(x)
    total = 0
    for j in range(L):
        u, v, w, cid = cal.edges[ids[j]]
        u2, v2, w2, c2 = cal.edges[ids[(j + 1) % L]]
        if v != u2:
            return False
        total += w
    return total < 0


def check_calib_artifact(cal, art):
    """Validate a feasible calibration certificate for cal's profile."""
    if not isinstance(art, dict):
        return False
    if art.get('status') != 'ok':
        return False
    up = art.get('upper_ps')
    pr = art.get('pred')
    K = cal.K
    if not isinstance(up, list) or len(up) != K:
        return False
    if not isinstance(pr, list) or len(pr) != K:
        return False
    for a in range(K):
        row = up[a]
        prow = pr[a]
        if not isinstance(row, list) or len(row) != K:
            return False
        if not isinstance(prow, list) or len(prow) != K:
            return False
        for b in range(K):
            if not _is_int(row[b]):
                return False
        if row[a] != 0:
            return False
        if prow[a] is not None:
            return False
    # every row must be a feasible bias vector with its source entry zero
    for a in range(K):
        x = up[a]
        for (u, v, lo, hi) in cal.meas:
            d = x[v] - x[u]
            if d < lo or d > hi:
                return False
    # predecessor chains must be tight paths back to the source
    for a in range(K):
        memo = {}
        for b in range(K):
            if b == a:
                continue
            path = []
            cur = b
            while cur != a and cur not in memo:
                cid = pr[a][cur]
                if not _is_int(cid):
                    return False
                if cid < 0 or cid >= 2 * cal.m:
                    return False
                u, v, w, c2 = cal.edges[cid]
                if v != cur:
                    return False
                path.append(cur)
                cur = u
                if len(path) > K:
                    return False
            if cur == a:
                base = 0
            elif cur in memo:
                base = memo[cur]
            else:
                return False
            s = base
            for node in reversed(path):
                cid = pr[a][node]
                s += cal.edges[cid][2]
                memo[node] = s
            if memo[b] != up[a][b]:
                return False
    return True
