def _check_cycle(cyc, K, meas):
    """Validate a negative-cycle inconsistency proof."""
    if not isinstance(cyc, list):
        return False
    n = len(cyc)
    if n < 1 or n > K:
        return False
    M = len(meas)
    total = 0
    first_src = None
    prev_dst = None
    for e in cyc:
        if not is_int(e) or e < 0 or e >= 2 * M:
            return False
        i, dirc = divmod(e, 2)
        a, b, lo, hi = meas[i]
        if dirc == 0:
            s, t, w = a, b, hi
        else:
            s, t, w = b, a, -lo
        if first_src is None:
            first_src = s
        elif s != prev_dst:
            return False
        prev_dst = t
        total += w
    if prev_dst != first_src:
        return False
    return total < 0


def _check_cal_cert(art, K, meas):
    """Independently verify a feasible calibration certificate."""
    if not isinstance(art, dict):
        return False
    if art.get('status') != 'ok':
        return False
    up = art.get('upper_ps')
    pr = art.get('pred')
    if not isinstance(up, list) or len(up) != K:
        return False
    if not isinstance(pr, list) or len(pr) != K:
        return False
    M = len(meas)
    for a in range(K):
        row = up[a]
        prow = pr[a]
        if not isinstance(row, list) or len(row) != K:
            return False
        if not isinstance(prow, list) or len(prow) != K:
            return False
        if not is_int(row[a]) or row[a] != 0:
            return False
        if prow[a] is not None:
            return False
        for b in range(K):
            if not is_int(row[b]):
                return False
            if b == a:
                continue
            cell = prow[b]
            if not is_int(cell) or cell < 0 or cell >= 2 * M:
                return False
            i, dirc = divmod(cell, 2)
            x, y, lo, hi = meas[i]
            if dirc == 0:
                if y != b:
                    return False
            else:
                if x != b:
                    return False
    # every row is a feasible bias vector with its source entry zero
    for a in range(K):
        row = up[a]
        for (x, y, lo, hi) in meas:
            d = row[y] - row[x]
            if d < lo or d > hi:
                return False
    # predecessor chains reach the source and sum to the claimed bound
    for a in range(K):
        row = up[a]
        prow = pr[a]
        state = [0] * K
        accw = [0] * K
        state[a] = 2
        for b in range(K):
            if b == a or state[b] != 0:
                continue
            path = []
            cur = b
            while state[cur] == 0:
                e = prow[cur]
                i, dirc = divmod(e, 2)
                x, y, lo, hi = meas[i]
                w = hi if dirc == 0 else -lo
                nxt = x if dirc == 0 else y
                path.append((cur, w))
                state[cur] = 1
                cur = nxt
            if state[cur] != 2:
                return False
            total = accw[cur]
            for (node, w) in reversed(path):
                total += w
                accw[node] = total
                state[node] = 2
        for b in range(K):
            if b != a and accw[b] != row[b]:
                return False
    return True


