    std::cout << ",\"front16\":";
    fronts(d.front16, 4);
    std::cout << ",\"front64\":";
    fronts(d.front64, 16);
    std::cout << ",\"cells\":[";
    for (int s = 0; s < RAM_NUM; ++s) {
        if (s) std::cout << ',';
        std::cout << d.cells[s];
    }
    std::cout << "],\"banks\":[";
    for (int s = 0; s < RAM_NUM; ++s) {
        if (s) std::cout << ',';
        std::cout << '[';
        bool first = true;
        for (size_t i = 0; i < d.banks[s].size(); ++i) {
            if (!first) std::cout << ',';
            first = false;
            std::cout << '"' << image_word_hex(d.banks[s][i]) << '"';
        }
        std::cout << ']';
    }
    std::cout << "],\"bitmaps\":[";
    for (size_t i = 0; i < d.bitmaps.size(); ++i) {
