                  });
    } else if (type == 4) {
        if (!zero_bits(row, off + 119, 9)) return false;
        ImageNode::Inl in;
        if (!parse_inline(getbits(row, off + 25, 64), (int)getbits(row, off + 89, 8),
                          (uint32_t)getbits(row, off + 97, 22), t.origin, t.depth,
                          t.region, in))
            return false;
        n.inls.push_back(in);
    } else { // type == 5
        if (!zero_bits(row, off + 213, 43)) return false;
        for (int i = 0; i < 2; ++i) {
            ImageNode::Inl in;
            if (!parse_inline(getbits(row, off + 25 + 94 * i, 64),
                              (int)getbits(row, off + 89 + 94 * i, 8),
                              (uint32_t)getbits(row, off + 97 + 94 * i, 22),
                              t.origin, t.depth, t.region, in))
                return false;
            n.inls.push_back(in);
        }
        if (n.inls[0].len == n.inls[1].len && n.inls[0].addr == n.inls[1].addr)
            return false;                                  // distinct prefixes
    }

    rep.at[lk] = idx;
    rep.nodes.push_back(n);
    slots[t.stage].push_back(std::make_pair(t.cell, slot));
    for (size_t i = 0; i < children.size(); ++i) stack.push_back(children[i]);
}

// ---- charged slots cover [0,cells[stage]) densely and without overlap --
for (int s = 0; s < RAM_NUM; ++s) {
    std::vector<std::pair<uint32_t, int> >& v = slots[s];
    std::sort(v.begin(), v.end());
    uint32_t pos = 0;
    for (size_t i = 0; i < v.size(); ++i) {
        if (v[i].first != pos) return false;
        pos += (uint32_t)v[i].second;
    }
    if (pos != d.cells[s]) return false;
}

// ---- roots and fronts resolve to nodes --------------------------------
if (d.root.stage >= 0) {
    std::unordered_map<uint64_t, int>::const_iterator it =
        rep.at.find(loc_key(d.root.stage, d.root.cell));
    if (it == rep.at.end()) return false;
    rep.rootIdx = it->second;
}
for (int f = 0; f < 2; ++f) {
    const std::vector<ImageFront>& v = *fronts[f];
    std::unordered_map<uint64_t, int>& dst = (f == 0) ? rep.f16 : rep.f64;
    for (size_t i = 0; i < v.size(); ++i) {
        std::unordered_map<uint64_t, int>::const_iterator it =
            rep.at.find(loc_key(v[i].loc.stage, v[i].loc.cell));
        if (it == rep.at.end()) return false;
        dst[v[i].key] = it->second;
    }
}

// ---- NI ranges and represented prefixes -------------------------------
std::vector<std::pair<uint32_t, uint32_t> > ranges;
PrefixTrie trie;
size_t fibCount = 0;

for (size_t i = 0; i < rep.nodes.size(); ++i) {
    ImageNode& n = rep.nodes[i];
    if (n.type <= 3) {
        uint64_t pop = (uint64_t)__builtin_popcountll(n.bm);
        if (pop == 0) {
            if (n.nibase != 0) return false;         // empty arrays have base 0
        } else {
            if ((uint64_t)n.nibase + pop > d.nexthops.size()) return false;
            ranges.push_back(std::make_pair(n.nibase, n.nibase + (uint32_t)pop));
        }
        int rank = 0;
        uint64_t bm = n.bm;
        while (bm) {
            int p = __builtin_ctzll(bm);
            bm &= bm - 1;
            if (p == 0) return false;                // bit0 is unused
            int l = floor_log2((uint64_t)p);         // l in 0..5
            uint64_t v = (uint64_t)p - (1ULL << l);
            int L = n.depth + l;
            if (!origin_len_ok(n.origin, L)) return false;
            ip6_t addr = n.region;
            set_bits(addr, n.depth, l, v);
            nexthop_t hop = d.nexthops[n.nibase + rank];
            if (!trie.insert(addr, L, hop)) return false; // no duplicated prefixes
            ++fibCount;
            ++rank;
        }
    } else {
        for (size_t j = 0; j < n.inls.size(); ++j) {
            if (!trie.insert(n.inls[j].addr, n.inls[j].len, n.inls[j].hop))
                return false;
            ++fibCount;
        }
    }
}
if (fibCount != trie.inserted()) return false;
if (fibCount > 8192) return false;                    // complete FIB bound

// NI arrays are disjoint and cover the complete NI vector without holes
std::sort(ranges.begin(), ranges.end());
uint32_t pos = 0;
for (size_t i = 0; i < ranges.size(); ++i) {
    if (ranges[i].first != pos) return false;
    pos = ranges[i].second;
}
if (pos != d.nexthops.size()) return false;

// all patterns must be used
for (size_t i = 0; i < usedBitmap.size(); ++i)
    if (!usedBitmap[i]) return false;

rep.nexthops = d.nexthops;

// ---- subtree ownership sizes -----------------------------------------
// children always come after their parents in `nodes`, so a reverse pass
// is a post-order traversal.
for (size_t i = rep.nodes.size(); i-- > 0;) {
    ImageNode& n = rep.nodes[i];
    uint64_t owned = (n.type <= 3) ? (uint64_t)__builtin_popcountll(n.bm)
                                   : (uint64_t)n.inls.size();
    for (size_t j = 0; j < n.kids.size(); ++j) {
        std::unordered_map<uint64_t, int>::const_iterator it =
            rep.at.find(loc_key(n.kids[j].stage, n.kids[j].cell));
        if (it == rep.at.end()) return false;        // all locators resolve
        owned += rep.nodes[it->second].owned;
    }
    if (n.type <= 3) {
        if (owned < 3) return false;                 // 1/2-owned subtrees are TYPE4/5
    } else if (owned != n.inls.size()) {
        return false;
    }
    n.owned = owned;
}

#!/usr/bin/env python3
"""Public examples only. Run inside the candidate's public workspace."""
import json
import math
import pathlib
import subprocess
import sys
import tempfile


def unique(items):
    out = {}
    for k, v in items:
        if k in out:
            raise ValueError('duplicate output key')
        out[k] = v
    return out


def equal(expected, actual):
    if type(expected) is dict:
        return (type(actual) is dict and expected.keys() == actual.keys()
                and all(equal(v, actual[k]) for k, v in expected.items()))
    if type(expected) is list:
        return (type(actual) is list and len(expected) == len(actual)
                and all(equal(a, b) for a, b in zip(expected, actual)))
    if type(expected) is float:
        return type(actual) in (int, float) and math.isfinite(actual) and abs(expected - actual) <= 1e-8
    return type(expected) is type(actual) and expected == actual


def main():
    root = pathlib.Path(__file__).resolve().parent
    failures = 0
    for source in sorted((root / 'examples').glob('*.input.json')):
        expected = json.loads(source.with_name(source.name.replace('.input.', '.expected.')).read_text())
        try:
            # File-backed capture keeps the checker's own memory bounded.
            with tempfile.TemporaryFile() as stdout, tempfile.TemporaryFile() as stderr:
                result = subprocess.run([sys.executable, '-I', str(root / 'submission/main.py')],
                                        input=source.read_bytes(), stdout=stdout, stderr=stderr,
                                        cwd=root, timeout=90)
                stdout.seek(0)
                raw = stdout.read(16777217)
                if len(raw) > 16777216:
                    raise ValueError('output too large')
                actual = json.loads(raw, object_pairs_hook=unique,
                                    parse_constant=lambda x: (_ for _ in ()).throw(ValueError(x)))
                passed = result.returncode == 0 and equal(expected, actual)
        except (ValueError, OSError, subprocess.TimeoutExpired):
            passed = False
        print(('PASS ' if passed else 'FAIL ') + source.name)
        failures += int(not passed)
    print('Public examples only; additional networks are evaluated separately.')
    return int(failures > 0)


if __name__ == '__main__':
    raise SystemExit(main())

#!/usr/bin/env python3
"""Prior-only baseline: path cleanup and scoring, without joint inference.

This deliberately treats every observed link as removed in round one.
It is useful on one-link RIBs, but core topology and probabilities need work.
"""
import json
import sys
from fractions import Fraction


def clean(path, ixps):
    result = []
    for asn in path:
        if asn not in ixps and (not result or result[-1] != asn):
            result.append(asn)
    return result


def canonical(a, b):
    return min(a, b), max(a, b)


def baseline(data):
    ixps = set(data['ixps'])
    uniform = (Fraction(1, 3),) * 3
    priors, declared = {}, {}
    for record in data['priors']:
        a, b = record['link']
        weights = record['weights']
        p = tuple(Fraction(v, sum(weights)) for v in weights)
        priors[canonical(a, b)] = p if a < b else p[::-1]
    for record in data['declared']:
        a, b = record['link']
        p = tuple(Fraction(int(record['rel'] == rel)) for rel in ('c2p', 'p2p', 'p2c'))
        declared[canonical(a, b)] = p if a < b else p[::-1]
    seen = set()
    for record in data['rib']:
        p = clean(record['path'], ixps)
        if len(set(p)) == len(p):
            seen.update(canonical(a, b) for a, b in zip(p, p[1:]))
    links = [dict(link=list(e), round=1, prob=list(map(float, priors.get(e, uniform))))
             for e in sorted(seen)]
    queries = []
    for record in data['queries']:
        p = clean(record['path'], ixps)
        answer = dict(id=record['id'], path=p, status='ok', score=None,
                      full=None, witness=None, leaked=None)
        if len(set(p)) != len(p):
            answer['status'] = 'loop'
        else:
            probabilities = []
            for a, b in zip(p, p[1:]):
                e = canonical(a, b)
                v = declared.get(e, priors.get(e, uniform))
                probabilities.append(v if a < b else v[::-1])
            triples = [x[0] + y[2] - x[0] * y[2]
                       for x, y in zip(probabilities, probabilities[1:])]
            score = min(triples) if triples else Fraction(1)
            up, peer, down = Fraction(1), Fraction(0), Fraction(0)
            for a, b, c in probabilities:
                up, peer, down = up * a, up * b, (up + peer + down) * c
            answer.update(score=float(score), full=float(up + peer + down),
                          witness=triples.index(score) if triples else None,
                          leaked=score < Fraction(*record['threshold']))
        queries.append(answer)
    return dict(version=1, links=links, queries=queries)


if __name__ == '__main__':
    try:
        answer = baseline(json.load(sys.stdin))
    except (ValueError, TypeError, KeyError, IndexError, ZeroDivisionError):
        answer = {'error': 'invalid'}
    print(json.dumps(answer, allow_nan=False))

