def fmul(a, b):
    v1, t1 = a
    v2, t2 = b
    s1 = set(v1)
    s2 = set(v2)
    u = sorted(s1 | s2)
    ku = len(u)
    k1 = len(v1)
    k2 = len(v2)
    w1 = [0] * ku
    w2 = [0] * ku
    for j, v in enumerate(u):
        if v in s1:
            w1[j] = 3 ** (k1 - 1 - v1.index(v))
        if v in s2:
            w2[j] = 3 ** (k2 - 1 - v2.index(v))
    n = 3 ** ku
    res = [0] * n
    digits = [0] * ku
    i1 = 0
    i2 = 0
    for iu in range(n):
        res[iu] = t1[i1] * t2[i2]
        j = ku - 1
        while j >= 0:
            digits[j] += 1
            i1 += w1[j]
            i2 += w2[j]
            if digits[j] < 3:
                break
            digits[j] = 0
            i1 -= 3 * w1[j]
            i2 -= 3 * w2[j]
            j -= 1
    return (u, res)


def fsum(a, x):
    v, t = a
    k = len(v)
    j = v.index(x)
    stride = 3 ** (k - 1 - j)
    nv = v[:j] + v[j + 1:]
    nlen = stride
    nt = [0] * nlen
    for iu, val in enumerate(t):
        hi = iu // (stride * 3)
        lo = iu % stride
        nt[hi * stride + lo] += val
    return (nv, nt)


def eliminate(factors, order_idx, skip):
    """Eliminate every variable except `skip`; return remaining factor."""
    fs = list(factors)
    for x in order_idx:
        if x == skip:
            continue
        bucket = []
        rest = []
        for f in fs:
            if x in f[0]:
                bucket.append(f)
            else:
                rest.append(f)
        acc = bucket[0]
        for f in bucket[1:]:
            acc = fmul(acc, f)
        acc = fsum(acc, x)
        rest.append(acc)
        fs = rest
    out = ([], [1])
    for f in fs:
        out = fmul(out, f)
    return out


