        mode, reason = 'ip', 'disabled'
    else:
        bad = False
        for i in f['k_off']:
            if hb[i] != tb[i]:
                bad = True
                break
        if bad:
            mode, reason = 'ip', 'mismatch'
        elif hb[f['q_off']] > 7:
            mode, reason = 'ip', 'qos'
        else:
            mode, reason = 'mpls', 'compressed'
    t = hb[f['t_off']]
    n = len(f['path'])
    payload = bytes.fromhex(pay)
