        if mode == 'mpls':
            q = hb[f['q_off']]
            residue = bytes(hb[i] for i in f['d_off'])
            sent = 0
            for i in range(n):
                if i and t - (i - 1) <= 1:
                    break
                ttl = t - i
                word = (f['labels'][i] << 12) | (q << 9) | 0x100 | ttl
                wire.append(word.to_bytes(4, 'big') + residue + payload)
                sent += 1
            if sent == n:
                hb2 = bytearray(f['H'])
                for i in f['k_off']:
                    hb2[i] = tb[i]
                for idx, off in enumerate(f['d_off']):
                    hb2[off] = residue[idx]
                hb2[f['q_off']] = q
                hb2[f['t_off']] = t - (n - 1)
                delivered = (bytes(hb2) + payload).hex()
        else:
            sent = 0
            for i in range(n):
                if i and t - (i - 1) <= 1:
                    break
                ttl = t - i
                h2 = bytearray(hb)
                h2[f['t_off']] = ttl
                wire.append(bytes(h2) + payload)
                sent += 1
            if sent == n:
                delivered = wire[-1].hex()
    return {'mode': mode, 'reason': reason,
            'wire': [w.hex() for w in wire],
            'delivered': delivered,
            'byte_hops': sum(len(w) for w in wire)}


def _run_replay(cap, flowmap, events):
    tables = {}
    node_count = {}
    enabled = set()
    results = []
    for ev in events:
        op = ev[0]
        if op == 'put':
            fid = ev[1]
            nd = ev[2]
