"""Selective header-compression engine: offline replay and admission planning.

Implements "Selective header-compression protocol v1.1": strict JSON framing,
control/data-plane replay with checked dictionary compression over MPLS label
swapping, and exact offline admission planning.  Standard library only.
"""
import json
import math
import re
import sys

ID_RE = re.compile(r'[A-Za-z0-9_.-]{1,32}\Z')
HEX_RE = re.compile(r'[0-9a-f]*\Z')
TOP_REPLAY = frozenset(('mode', 'capacities', 'flows', 'events'))
TOP_PLAN = frozenset(('mode', 'capacities', 'flows', 'warmup', 'pinned', 'offers'))


class Bad(Exception):
    """Schema violation: respond exactly {"error":"input"}."""


# ---------------------------------------------------------------- JSON parse

def _pairs(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Bad()
        d[k] = v
    return d


def _const(_s):
    raise Bad()


# ------------------------------------------------------------- value helpers

def _int(v):
    if isinstance(v, bool):
        raise Bad()
    if isinstance(v, int):
        return v
    if isinstance(v, float) and math.isfinite(v) and v.is_integer():
        return int(v)
    raise Bad()


def _ir(v, lo, hi):
    x = _int(v)
    if x < lo or x > hi:
        raise Bad()
    return x


def _st(v):
    if not isinstance(v, str):
        raise Bad()
    return v


def _ls(v):
    if not isinstance(v, list):
        raise Bad()
    return v


def _ob(v):
    if not isinstance(v, dict):
        raise Bad()
    return v


def _hexs(v, empty=False):
    s = _st(v)
    if not empty and not s:
        raise Bad()
    if (len(s) & 1) or not HEX_RE.match(s):
        raise Bad()
    return s


# ---------------------------------------------------------------- validation

def _capacities(v):
    caps = _ob(v)
    if not 1 <= len(caps) <= 64:
        raise Bad()
    out = {}
    for k, val in caps.items():
        if not ID_RE.match(k):
            raise Bad()
        out[k] = _ir(val, 0, 512)
    return out


def _parse_flow(fd, cap, replay):
    keys = {'id', 'path', 'template', 'kinds'}
    if replay:
        keys.add('labels')
    if set(fd.keys()) != keys:
        raise Bad()
    fid = _st(fd['id'])
    if not ID_RE.match(fid):
        raise Bad()
    path = _ls(fd['path'])
    if not 2 <= len(path) <= 9:
        raise Bad()
    p = []
    for x in path:
        nd = _st(x)
        if nd not in cap or nd in p:
            raise Bad()
        p.append(nd)
    tmpl = _hexs(fd['template'])
    H = len(tmpl) // 2
    if not 8 <= H <= 256:
        raise Bad()
    kinds = _st(fd['kinds'])
    if len(kinds) != H:
        raise Bad()
    if any(c not in 'KDZQT' for c in kinds):
        raise Bad()
    qn = kinds.count('Q')
    tn = kinds.count('T')
    kn = kinds.count('K')
    dn = kinds.count('D')
    if qn != 1 or tn != 1 or kn < 1 or 4 + dn >= H:
        raise Bad()
    labels = []
    if replay:
        labs = _ls(fd['labels'])
        if len(labs) != len(p):
            raise Bad()
        for l in labs:
            labels.append(_ir(l, 16, 1048575))
    return {
        'id': fid, 'path': p, 'H': H, 'kinds': kinds, 'labels': labels,
        'tmpl': tmpl, 'tmpl_bytes': bytes.fromhex(tmpl),
        'k_off': [i for i, c in enumerate(kinds) if c == 'K'],
        'd_off': [i for i, c in enumerate(kinds) if c == 'D'],
        'q_off': kinds.index('Q'), 't_off': kinds.index('T'),
    }


def _flows(v, cap, replay):
    fls = _ls(v)
    if len(fls) > (512 if replay else 22):
        raise Bad()
    out = {}
    for fd in fls:
        f = _parse_flow(_ob(fd), cap, replay)
        if f['id'] in out:
            raise Bad()
        out[f['id']] = f
    return out


def _events(v, flowmap):
    evs = _ls(v)
    if len(evs) > 20000:
        raise Bad()
    total = 0
    out = []
    for ev in evs:
        e = _ob(ev)
        if 'op' not in e:
            raise Bad()
        op = _st(e['op'])
        if op == 'put':
            if set(e.keys()) != {'op', 'flow', 'node'}:
                raise Bad()
            fid = _st(e['flow'])
            f = flowmap.get(fid)
            if f is None:
                raise Bad()
            nd = _st(e['node'])
            if nd not in f['path']:
                raise Bad()
            out.append(('put', fid, nd))
        elif op == 'enable' or op == 'disable':
            if set(e.keys()) != {'op', 'flow'}:
                raise Bad()
            fid = _st(e['flow'])
            if fid not in flowmap:
                raise Bad()
            out.append((op, fid))
        elif op == 'reset':
            if set(e.keys()) != {'op'}:
                raise Bad()
            out.append(('reset',))
        elif op == 'packet':
            if set(e.keys()) != {'op', 'flow', 'header', 'payload'}:
                raise Bad()
            fid = _st(e['flow'])
            f = flowmap.get(fid)
            if f is None:
                raise Bad()
            hdr = _hexs(e['header'])
            if len(hdr) != 2 * f['H']:
                raise Bad()
            pay = _hexs(e['payload'], empty=True)
            if len(pay) // 2 > 2048:
                raise Bad()
            total += len(hdr) // 2 + len(pay) // 2
            if total > 2 * 1024 * 1024:
                raise Bad()
            out.append(('packet', fid, hdr, pay))
        else:
            raise Bad()
    return out


# ------------------------------------------------------------ replay engine

def _packet(f, hdr, pay, enabled):
    hb = bytes.fromhex(hdr)
    tb = f['tmpl_bytes']
    if f['id'] not in enabled:
        mode, reason = 'ip', 'disabled'
    else:
        bad = False
        for i in f['k_off']:
            if hb[i] != tb[i]:
                bad = True
                break
        if bad:
            mode, reason = 'ip', 'mismatch'
        elif hb[f['q_off']] > 7:
            mode, reason = 'ip', 'qos'
        else:
            mode, reason = 'mpls', 'compressed'
    t = hb[f['t_off']]
    n = len(f['path'])
    payload = bytes.fromhex(pay)
    wire = []
    delivered = None
    if t > 0:
        if mode == 'mpls':
            q = hb[f['q_off']]
            residue = bytes(hb[i] for i in f['d_off'])
            sent = 0
            for i in range(n):
                if i and t - (i - 1) <= 1:
                    break
                ttl = t - i
                word = (f['labels'][i] << 12) | (q << 9) | 0x100 | ttl
                wire.append(word.to_bytes(4, 'big') + residue + payload)
                sent += 1
            if sent == n:
                hb2 = bytearray(f['H'])
                for i in f['k_off']:
                    hb2[i] = tb[i]
                for idx, off in enumerate(f['d_off']):
                    hb2[off] = residue[idx]
                hb2[f['q_off']] = q
                hb2[f['t_off']] = t - (n - 1)
                delivered = (bytes(hb2) + payload).hex()
        else:
            sent = 0
            for i in range(n):
                if i and t - (i - 1) <= 1:
                    break
                ttl = t - i
                h2 = bytearray(hb)
                h2[f['t_off']] = ttl
                wire.append(bytes(h2) + payload)
                sent += 1
            if sent == n:
                delivered = wire[-1].hex()
    return {'mode': mode, 'reason': reason,
            'wire': [w.hex() for w in wire],
            'delivered': delivered,
            'byte_hops': sum(len(w) for w in wire)}


def _run_replay(cap, flowmap, events):
    tables = {}
    node_count = {}
    enabled = set()
    results = []
    for ev in events:
        op = ev[0]
        if op == 'put':
            fid = ev[1]
            nd = ev[2]
            f = flowmap[fid]
            label = f['labels'][f['path'].index(nd)]
            cur = tables.get((nd, label))
            if cur == fid:
                results.append({'status': 'ok'})
            elif cur is not None and cur in enabled:
                results.append({'status': 'busy'})
            elif cur is None and node_count.get(nd, 0) >= cap[nd]:
                results.append({'status': 'full'})
            else:
                tables[(nd, label)] = fid
                if cur is None:
                    node_count[nd] = node_count.get(nd, 0) + 1
                results.append({'status': 'ok'})
        elif op == 'enable':
            fid = ev[1]
            if fid in enabled:
                results.append({'status': 'ok'})
            else:
                f = flowmap[fid]
                ok = True
                for i, nd in enumerate(f['path']):
                    if tables.get((nd, f['labels'][i])) != fid:
                        ok = False
                        break
                if ok:
                    enabled.add(fid)
                    results.append({'status': 'ok'})
                else:
                    results.append({'status': 'unready'})
        elif op == 'disable':
            enabled.discard(ev[1])
            results.append({'status': 'ok'})
        elif op == 'reset':
            enabled.clear()
            results.append({'status': 'ok'})
        else:
            results.append(_packet(flowmap[ev[1]], ev[2], ev[3], enabled))
    active = sorted(enabled)
    tlist = [{'node': k[0], 'label': k[1], 'flow': v}
             for k, v in sorted(tables.items(), key=lambda kv: (kv[0][0], kv[0][1]))]
    return {'results': results, 'active': active, 'tables': tlist}


# -------------------------------------------------------------- plan engine

def _solve_comp(items, resv):
    """Exact best subset of items under per-lane capacities.

    items: list of (benefit, lane_bits, tag).  lane_bits encodes one unit per
    used lane in 32-bit lanes (value in low 16 bits).  resv: residual capacity
    per lane.  Returns (best_benefit, best_count, [tags]) with max benefit and
    then min count.
    """
    n = len(items)
    if n == 0:
        return 0, 0, []
    n1 = n // 2
    A = items[:n1]
    B = items[n1:]
    cap = 0
    guard = 0
    for lane, r in enumerate(resv):
        cap |= r << (32 * lane)
        guard |= 0xFFFF << (32 * lane + 16)
    capg = cap | guard

    m2 = 1 << len(B)
    ub = [0] * m2
    bb = [0] * m2
    cb = [0] * m2
    for mask in range(1, m2):
        lb = mask & -mask
        i = lb.bit_length() - 1
        prev = mask ^ lb
        ub[mask] = ub[prev] + B[i][1]
        bb[mask] = bb[prev] + B[i][0]
        cb[mask] = cb[prev] + 1
    groups = {}
    for mask in range(m2):
        key = ub[mask]
        cur = groups.get(key)
        if cur is None or bb[mask] > cur[0] or (bb[mask] == cur[0] and cb[mask] < cur[1]):
            groups[key] = (bb[mask], cb[mask], mask)
    glist = sorted(groups.values(), key=lambda t: (-t[0], t[1]))

    m1 = 1 << len(A)
    ua = [0] * m1
    ba = [0] * m1
    ca = [0] * m1
    best_b = -1
    best_c = 0
    best_a = 0
    best_g = 0
    for mask in range(m1):
        if mask:
            lb = mask & -mask
            i = lb.bit_length() - 1
            prev = mask ^ lb
            ua[mask] = ua[prev] + A[i][1]
            ba[mask] = ba[prev] + A[i][0]
            ca[mask] = ca[prev] + 1
        u = ua[mask]
        if ((capg - u) & guard) != guard:
            continue
        rg = (cap - u) | guard
        base = ba[mask]
        nca = ca[mask]
        for gb, gc, gmask in glist:
            tot = base + gb
            if tot < best_b:
                break
            if ((rg - ub[gmask]) & guard) == guard:
                cnt = nca + gc
                if tot > best_b or (tot == best_b and cnt < best_c):
                    best_b = tot
                    best_c = cnt
                    best_a = mask
                    best_g = gmask
    tags = []
    for i in range(len(A)):
        if (best_a >> i) & 1:
            tags.append(A[i][2])
    for i in range(len(B)):
        if (best_g >> i) & 1:
            tags.append(B[i][2])
    return best_b, best_c, tags


def _plan_solve(cands, res):
    """Choose a max-benefit, min-count subset of cands under node residuals."""
    n = len(cands)
    if n == 0:
        return []
    cnt = {}
    for f in cands:
        for nd in f['path']:
            cnt[nd] = cnt.get(nd, 0) + 1
    binding = set(nd for nd, c in cnt.items() if res[nd] < c)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for nd in binding:
        members = [i for i, f in enumerate(cands) if nd in f['path']]
        r0 = find(members[0])
        for i in members[1:]:
            ri = find(i)
            if ri != r0:
                parent[ri] = r0
    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)
    chosen = []
    for members in groups.values():
        lanes = sorted(set(nd for i in members for nd in cands[i]['path']) & binding)
        lidx = {}
        for j, nd in enumerate(lanes):
            lidx[nd] = j
        resv = [res[nd] for nd in lanes]
        items = []
        for i in members:
            f = cands[i]
            bits = 0
            for nd in f['path']:
                if nd in lidx:
                    bits |= 1 << (32 * lidx[nd])
            items.append((f['benefit'], bits, f['id']))
        _b, _c, tags = _solve_comp(items, resv)
        chosen.extend(tags)
    return chosen


def _run_plan(cap, flowmap, flows, warmup, pins, runs_by_flow):
    benefits = {}
    for f in flows:
        n = len(f['path'])
        h = n - 1
        per = (f['H'] - 4 - len(f['d_off'])) * n
        left = warmup
        elig = 0
        t_off = f['t_off']
        q_off = f['q_off']
        k_off = f['k_off']
        tb = f['tmpl_bytes']
        for hb, c in runs_by_flow[f['id']]:
            if left >= c:
                left -= c
                continue
            c -= left
            left = 0
            if hb[t_off] > h and hb[q_off] <= 7:
                good = True
                for i in k_off:
                    if hb[i] != tb[i]:
                        good = False
                        break
                if good:
                    elig += c
        benefits[f['id']] = per * elig

    use = {}
    for fid in pins:
        for nd in flowmap[fid]['path']:
            use[nd] = use.get(nd, 0) + 1
    for nd, c in use.items():
        if c > cap[nd]:
            return {'infeasible': True}
    res = dict(cap)
    for nd, c in use.items():
        res[nd] = cap[nd] - c

    pinned = set(pins)
    cands = []
    for f in flows:
        if f['id'] not in pinned and benefits[f['id']] > 0:
            cands.append({'id': f['id'], 'path': f['path'],
                          'benefit': benefits[f['id']]})
    chosen = _plan_solve(cands, res)
    selected = sorted(pinned | set(chosen))
    saved = 0
    for fid in selected:
        saved += benefits[fid]
    return {'selected': selected, 'saved': saved}


# ------------------------------------------------------------------ dispatch

def handle(req):
    top = _ob(req)
    keys = set(top.keys())
    if keys == TOP_REPLAY and top['mode'] == 'replay':
        cap = _capacities(top['capacities'])
        flowmap = _flows(top['flows'], cap, True)
        events = _events(top['events'], flowmap)
        return _run_replay(cap, flowmap, events)
    if keys == TOP_PLAN and top['mode'] == 'plan':
        cap = _capacities(top['capacities'])
        flowmap = _flows(top['flows'], cap, False)
        warmup = _ir(top['warmup'], 0, 1000000000)
        pins = []
        seen = set()
        for x in _ls(top['pinned']):
            s = _st(x)
            if not ID_RE.match(s) or s in seen or s not in flowmap:
                raise Bad()
            seen.add(s)
            pins.append(s)
        offers = _ob(top['offers'])
        if set(offers.keys()) != set(flowmap.keys()):
            raise Bad()
        run_bytes = 0
        runs_by_flow = {}
        for fid, rv in offers.items():
            runs = _ls(rv)
            if len(runs) > 256:
                raise Bad()
            f = flowmap[fid]
            tot = 0
            parsed = []
            for r in runs:
                rd = _ob(r)
                if set(rd.keys()) != {'header', 'count'}:
                    raise Bad()
                hdr = _hexs(rd['header'])
                if len(hdr) != 2 * f['H']:
                    raise Bad()
                c = _ir(rd['count'], 1, 1000000000)
                tot += c
                run_bytes += len(hdr) // 2
                parsed.append((bytes.fromhex(hdr), c))
            if tot > 1000000000:
                raise Bad()
            runs_by_flow[fid] = parsed
        if run_bytes > 65536:
            raise Bad()
        return _run_plan(cap, flowmap, list(flowmap.values()), warmup, pins, runs_by_flow)
    raise Bad()


def main():
    stdin = sys.stdin.buffer
    out = sys.stdout.buffer
    for raw in stdin:
        try:
            if len(raw) > 16 * 1024 * 1024:
                raise Bad()
            line = raw.decode('utf-8')
            req = json.loads(line, object_pairs_hook=_pairs, parse_constant=_const)
            resp = handle(req)
        except (Bad, ValueError, TypeError, KeyError, IndexError,
                OverflowError, RuntimeError, MemoryError):
            resp = {'error': 'input'}
        out.write(json.dumps(resp, separators=(',', ':')).encode('ascii'))
        out.write(b'\n')
        out.flush()


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Public examples only. Executes frozen candidate bytes in bounded children."""
import json
import math
import os
from pathlib import Path
import selectors
import shutil
import signal
import stat
import subprocess
import sys
import tempfile
import time
from limits import restrict_child

def strict_json(data):
    def pairs(items):
        out={}
        for k,v in items:
            if k in out:raise ValueError('duplicate key')
            out[k]=v
        return out
    def finite(v):
        x=float(v)
        if not math.isfinite(x):raise ValueError('nonfinite number')
        return x
    return json.loads(data.decode('utf-8'),object_pairs_hook=pairs,parse_float=finite,
                      parse_constant=lambda v:(_ for _ in ()).throw(ValueError(v)))


class CheckInterrupted(RuntimeError):
    pass


def run_child(path, data, temp):
    scratch = temp / 'scratch'
    scratch.mkdir()
    env = {'PATH': '/usr/local/bin:/usr/bin:/bin', 'HOME': '/workspace',
           'LANG': 'C', 'LC_ALL': 'C', 'TMPDIR': str(scratch),
           'PYTHONDONTWRITEBYTECODE': '1', 'PYTHONUNBUFFERED': '1',
           'PYTHONHASHSEED': '0', 'OMP_NUM_THREADS': '1',
           'OPENBLAS_NUM_THREADS': '1', 'MKL_NUM_THREADS': '1', 'PYTHONPATH':'/opt/deps'}
    started = time.monotonic()
    child = subprocess.Popen([sys.executable, '-B', '-u', str(path)],
                             stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                             stderr=subprocess.PIPE, cwd=scratch, env=env,
                             close_fds=True, start_new_session=True,
                             preexec_fn=restrict_child)
    sel = selectors.DefaultSelector()
    streams = [child.stdin, child.stdout, child.stderr]
    chunks = [bytearray(), bytearray()]
    offset = 0
    next_storage = started
    try:
        for stream in streams:
            os.set_blocking(stream.fileno(), False)
        if data:
            sel.register(child.stdin, selectors.EVENT_WRITE, -1)
        else:
            child.stdin.close()
        sel.register(child.stdout, selectors.EVENT_READ, 0)
        sel.register(child.stderr, selectors.EVENT_READ, 1)
        while sel.get_map():
            now = time.monotonic()
            if now - started >= 180:
                raise ValueError('wall limit exceeded')
            if now >= next_storage:
                size, count = 0, 0
                for base, dirs, files in os.walk(scratch, followlinks=False):
                    for name in dirs + files:
                        st = (Path(base)/name).lstat()
                        count += 1
                        if stat.S_ISREG(st.st_mode):
                            size += max(st.st_size, st.st_blocks*512)
                if size > 64*1024**2 or count > 4096:
                    raise RuntimeError('infrastructure: scratch emergency budget')
                next_storage = now + .25
            for key, _ in sel.select(.05):
                stream, channel = key.fileobj, key.data
                if channel == -1:
                    try:
                        offset += os.write(stream.fileno(), data[offset:offset+65536])
                    except BlockingIOError:
                        continue
                    except BrokenPipeError:
                        offset = len(data)
                    if offset == len(data):
                        sel.unregister(stream)
                        stream.close()
                else:
                    cap = (8*1024**2, 1024**2)[channel]
                    try:
                        block = os.read(stream.fileno(), min(65536, cap-len(chunks[channel])+1))
                    except BlockingIOError:
                        continue
                    if not block:
                        sel.unregister(stream)
                        stream.close()
                    elif len(chunks[channel])+len(block) > cap:
                        raise ValueError('output byte limit exceeded')
                    else:
                        chunks[channel].extend(block)
        code = child.wait(timeout=max(.001, 180-(time.monotonic()-started)))
        if code:
            raise ValueError('candidate returned nonzero')
        return strict_json(bytes(chunks[0]))
    finally:
        # Ignore repeated interrupts until this single no-fork child is reaped.
        previous = {sig: signal.signal(sig, signal.SIG_IGN)
                    for sig in (signal.SIGINT, signal.SIGTERM)}
        try:
            if child.poll() is None:
                child.kill()
            child.wait(timeout=5)
            sel.close()
            for stream in streams:
                stream.close()
            shutil.rmtree(scratch)
        finally:
