            o.push_back(',');
            json_uint(o, v[i].loc.cell);
            o.push_back(']');
        }
        o.push_back(']');
    }
    json_raw(o, ",\"cells\":[");
    for (int s = 0; s < RAM_NUM; ++s) {
        if (s) o.push_back(',');
        json_uint(o, d.cells[s]);
    }
    json_raw(o, "],\"banks\":[");
    for (int s = 0; s < RAM_NUM; ++s) {
        if (s) o.push_back(',');
        o.push_back('[');
        for (size_t i = 0; i < d.banks[s].size(); ++i) {
            if (i) o.push_back(',');
            o.push_back('"');
            json_word(o, d.banks[s][i]);
