def mask(v, L):
    if L <= 0: return 0
    if L >= 128: return v & ((1 << 128) - 1)
    return v & ~((1 << (128 - L)) - 1)

def bits_at(v, off, cnt):
    if cnt <= 0: return 0
    if off >= 128: return 0
    m = (1 << cnt) - 1
    sh = 128 - off - cnt
    if sh >= 0: return (v >> sh) & m
    return (v << (-sh)) & m

