"""Capacity bounded Democratic Trust Propagation repair."""

from collections import Counter
from hashlib import sha256
from heapq import heappush, heappop
from math import gcd

from .agreement import best_band_from_counts, PPM

_digest = sha256


class RepairResult:
    """Frozen, immutable repair evidence."""

    __slots__ = ('links', 'order', 'values', 'confidences', 'counter_items',
                 'cell_confidence')

    def __init__(self, links, order, values, confidences, counter_items):
        self.links = links
        self.order = order
        self.values = values
        self.confidences = confidences
        self.counter_items = counter_items
        # Per counter cell: (corrected, numerator, denominator).
        cells = {}
        for key, value, num, den in counter_items:
            cells[key] = (value, num, den)
        self.cell_confidence = cells


def _trial_samples(seed, trials, router, flow, pool):
    """Reproducible scenario values for one (router, flow) pair."""
    width = len(pool)
    if width == 0:
        return [0] * trials
    if width == 1 or len(set(pool)) == 1:
        return [pool[0]] * trials
    prefix = '%d:%d:' % (seed, router)
    a, b = flow
    suffix = ':%d:%d' % (a, b)
    out = []
    append = out.append
    for t in range(trials):
        word = _digest((prefix + str(t) + suffix).encode('ascii')).digest()
        pick = int.from_bytes(word[:8], 'big') % width
        append(pool[pick])
    return out


def compute_repair(topology, trials, epsilon, seed, counters, predictions,
                   predicted):
    """Freeze a repair certificate for the current measured state.

    ``counters`` maps every valid counter key to an integer or ``None``.
    ``predictions`` maps flows to clamped predicted loads and is only consulted
    when ``predicted`` is true (nonnull routing plan).
    """
    flows = topology.flows
    cap = topology.cap
    sigma = topology.sigma
    incident = topology.incident
    endpoints = topology.endpoints
    flow_keys = topology.flow_keys
    span = PPM - epsilon

    # Ordered baseline pools.
    pools = {}
    base_counts = {}
    for flow in flows:
        pool = []
        for key in flow_keys[flow]:
            value = counters.get(key)
            if value is not None:
                pool.append(value)
        if predicted:
            pool.append(predictions[flow])
        pools[flow] = pool
        counts = {}
        for value in pool:
            counts[value] = counts.get(value, 0) + trials
        base_counts[flow] = counts

    # Reproducible scenario identities and router conservation imbalances.
    samples = {}
    delta = {}
    for router in topology.node_ids:
        for flow in incident[router]:
            samples[(router, flow)] = _trial_samples(seed, trials, router, flow,
                                                     pools[flow])
    for router in topology.node_ids:
        balance = [0] * trials
        for flow in incident[router]:
            word = samples[(router, flow)]
            if sigma[(router, flow)] > 0:
                for t in range(trials):
                    balance[t] -= word[t]
            else:
                for t in range(trials):
                    balance[t] += word[t]
        delta[router] = balance

    bands = {router: {} for router in topology.node_ids}

    # Initial evidence for every (router, incident unfixed flow) pair.
    for router in topology.node_ids:
        local = bands[router]
        balance = delta[router]
        for flow in incident[router]:
            word = samples[(router, flow)]
            limit = cap[flow]
            values = []
            append = values.append
            if sigma[(router, flow)] > 0:
                for base, sample in zip(balance, word):
                    value = base + sample
                    append(0 if value < 0 else (limit if value > limit else value))
            else:
                for base, sample in zip(balance, word):
                    value = sample - base
                    append(0 if value < 0 else (limit if value > limit else value))
            local[flow] = best_band_from_counts(Counter(values), span)

    def evidence(flow):
        counts = dict(base_counts[flow])
        for router in endpoints[flow]:
            value, mass = bands[router][flow]
            counts[value] = counts.get(value, 0) + mass
        return best_band_from_counts(counts, span)

    candidates = {}
    supports = {}
    generation = {flow: 0 for flow in flows}
    values = {}
    confidences = {}
    order = []
    heap = []
    dirty = set(flows)
    fixed_count = 0
    total = len(flows)
    while fixed_count < total:
        for flow in dirty:
            candidate, support = evidence(flow)
            candidates[flow] = candidate
            supports[flow] = support
            generation[flow] += 1
            heappush(heap, (-support, flow[0], flow[1], generation[flow]))
        dirty.clear()
        while True:
            _, a, b, stamp = heappop(heap)
            flow = (a, b)
            if flow in values:
                continue
            if generation[flow] != stamp:
                continue
            break
        value = candidates[flow]
        support = supports[flow]
        values[flow] = value
        step = gcd(support, trials)
        confidences[flow] = (support // step, trials // step)
        order.append(flow)
        fixed_count += 1
        if fixed_count == total:
            break
        for router in endpoints[flow]:
            balance = delta[router]
            word = samples[(router, flow)]
            sign = -sigma[(router, flow)]
            for t in range(trials):
                balance[t] += sign * (value - word[t])
            local = bands[router]
            for other in incident[router]:
                if other in values:
                    continue
                dirty.add(other)
                limit = cap[other]
                w2 = samples[(router, other)]
                out = []
                push = out.append
                if sigma[(router, other)] > 0:
                    for base, sample in zip(balance, w2):
                        cand = base + sample
                        push(0 if cand < 0 else (limit if cand > limit else cand))
                else:
                    for base, sample in zip(balance, w2):
                        cand = sample - base
                        push(0 if cand < 0 else (limit if cand > limit else cand))
                local[other] = best_band_from_counts(Counter(out), span)

    links = []
    counter_items = []
    for flow in flows:
        value = values[flow]
        num, den = confidences[flow]
        links.append((flow[0], flow[1], value, num, den))
        for key in flow_keys[flow]:
            counter_items.append((key, value, num, den))
    return RepairResult(tuple(links), tuple(order), values, confidences,
                        tuple(counter_items))

"""Per-stream replay state machine: patches, routes, repairs and validation."""

from collections import OrderedDict
from math import gcd

from .agreement import PPM
from .repair import compute_repair
from .topology import Topology, EXTERNAL

DEMAND_LIMIT = 10 ** 9
PATCH_FIELDS = frozenset(('op', 'demands', 'counters'))
CELL_FIELDS = frozenset(('perturbed', 'ground_truth', 'corrected', 'confidence'))


class Stream:
    """Independent state, snapshots and memoization for one stream."""

    __slots__ = ('topo', 'trials', 'epsilon', 'seed', 'cutoff', 'bias', 'tau',
                 'gamma', 'slots', 'counters', 'demands', 'paths_present',
                 'route_entries', 'route_identity', 'snapshots', 'cache',
                 '_preds', '_clamped')

    def __init__(self, spec):
        self.topo = Topology(spec['topology'])
        settings = spec['settings']
        self.trials = settings['trials']
        self.epsilon = settings['epsilon']
        self.seed = settings['seed']
        self.cutoff = (settings['cutoff'][0], settings['cutoff'][1])
        self.bias = settings['bias']
        self.tau = settings['tau']
        self.gamma = (settings['gamma'][0], settings['gamma'][1])
        self.slots = settings['cache_slots']
        self.counters = dict.fromkeys(self.topo.counter_keys)
        self.demands = {}
        self.paths_present = False
        self.route_entries = {}
        self.route_identity = None
        self.snapshots = {}
        self.cache = OrderedDict()
        self._preds = None
        self._clamped = None

    # ---------------------------------------------------------------- events
    def handle(self, event):
        op = event['op']
        if op == 'patch':
            return {'op': 'patch', 'accepted': self.apply_patch(event)}
        if op == 'routes':
            self.apply_routes(event)
            return {'op': 'routes', 'accepted': True}
        if op == 'repair':
            return self.do_repair(event['id'])
        return self.do_validate(event['id'])

    # ----------------------------------------------------------------- patch
    def apply_patch(self, event):
        if set(event.keys()) != PATCH_FIELDS:
            return False
        demands = event['demands']
        cells = event['counters']
        if type(demands) is not list or type(cells) is not dict:
            return False
        topo = self.topo
        external = topo.external
        key_flow = topo.key_flow
        cap = topo.cap

        staged_demands = []
        seen = set()
        for entry in demands:
            if type(entry) is not list or len(entry) != 3:
                return False
            src, dst, value = entry
            if type(src) is not int or type(dst) is not int or type(value) is not int:
                return False
            if src == dst or src not in external or dst not in external:
                return False
            if value < 0 or value > DEMAND_LIMIT:
                return False
            pair = (src, dst)
            if pair in seen:
                return False
            seen.add(pair)
            staged_demands.append((pair, value))

        staged_counters = []
        for key, cell in cells.items():
            flow = key_flow.get(key)
            if flow is None:
                return False
            if cell is None:
                staged_counters.append((key, None))
                continue
            if type(cell) is not dict:
                return False
            if 'perturbed' not in cell:
                return False
            for field in cell:
                if field not in CELL_FIELDS:
                    return False
            perturbed = cell['perturbed']
            if perturbed is None:
                staged_counters.append((key, None))
                continue
            if type(perturbed) is not int:
                return False
            if perturbed < 0 or perturbed > cap[flow]:
                return False
            staged_counters.append((key, perturbed))

        counters = self.counters
        demands = self.demands
        for pair, value in staged_demands:
            if demands.get(pair) != value:
                self._preds = None
                self._clamped = None
            demands[pair] = value
        for key, value in staged_counters:
            counters[key] = value
        return True

    # ---------------------------------------------------------------- routes
    def apply_routes(self, event):
        """Replace the whole active routing plan; routes events are valid."""
        plan = event['paths']
        if plan is None:
            changed = self.paths_present
            self.paths_present = False
            self.route_entries = {}
            self.route_identity = None
        else:
            name_to_id = self.topo.name_to_id
            entries = {}
            identity = []
            for source_name, bundles in plan.items():
                source = name_to_id[source_name]
                for target_name, options in bundles.items():
                    target = name_to_id[target_name]
                    bundle = []
                    for option in options:
                        names = option['path']
                        weight = option['weight']
                        vertices = [name_to_id[names[0]]]
                        hops = []
                        for name in names[1:]:
                            current = name_to_id[name]
                            hops.append((vertices[-1], current))
                            vertices.append(current)
                        identity.append((source, target, tuple(vertices), weight))
                        bundle.append((tuple(hops), weight))
                    entries[(source, target)] = bundle
            identity.sort()
            identity = tuple(identity)
            changed = (not self.paths_present) or identity != self.route_identity
            self.paths_present = True
            self.route_entries = entries
            self.route_identity = identity
        if changed:
            self._preds = None
            self._clamped = None

    # ----------------------------------------------------------- predictions
    def predictions(self):
        preds = self._preds
        if preds is None:
            preds = self._compute_predictions()
            self._preds = preds
        return preds

    def repair_predictions(self):
        clamped = self._clamped
        if clamped is None:
            if not self.paths_present:
                clamped = {}
            else:
                preds = self.predictions()
                cap = self.topo.cap
                clamped = {flow: min(preds[flow], cap[flow]) for flow in preds}
            self._clamped = clamped
        return clamped

    def _compute_predictions(self):
        topo = self.topo
        demands = self.demands
        preds = {}
        outgoing = {}
        incoming = {}
        for (src, dst), value in demands.items():
            if not value:
                continue
            outgoing[src] = outgoing.get(src, 0) + value
            incoming[dst] = incoming.get(dst, 0) + value
        for node in topo.external:
            preds[(EXTERNAL, node)] = outgoing.get(node, 0)
            preds[(node, EXTERNAL)] = incoming.get(node, 0)
        if self.paths_present:
            entries = self.route_entries
            accumulator = {}
            for pair, value in demands.items():
                if not value:
                    continue
                bundle = entries.get(pair)
                if not bundle:
                    continue
                for hops, weight in bundle:
                    amount = value * weight
                    for hop in hops:
                        accumulator[hop] = accumulator.get(hop, 0) + amount
            for flow in topo.internal_flows:
                preds[flow] = accumulator.get(flow, 0) // 1000
        return preds

    # ---------------------------------------------------------------- repair
    def cache_key(self):
        topo = self.topo
        counters = self.counters
        measured = tuple([counters[key] for key in topo.counter_keys])
        demands = tuple(sorted((pair, value) for pair, value in self.demands.items() if value))
        return (measured, demands, self.route_identity, self.seed, self.trials,
                self.epsilon)

    def do_repair(self, snapshot_id):
        key = self.cache_key()
        cache = self.cache
        result = cache.get(key)
        hit = result is not None
        if hit:
            cache.move_to_end(key)
        else:
            result = compute_repair(self.topo, self.trials, self.epsilon,
                                    self.seed, self.counters,
                                    self.repair_predictions(),
                                    self.paths_present)
            if self.slots:
                cache[key] = result
                while len(cache) > self.slots:
                    cache.popitem(last=False)
        self.snapshots[snapshot_id] = result
        return {'op': 'repair', 'id': snapshot_id, 'cache_hit': hit,
                'links': [[a, b, v, n, d] for a, b, v, n, d in result.links],
                'order': [[a, b] for a, b in result.order],
                'counters': {key: {'corrected': value, 'confidence': [num, den]}
                             for key, value, num, den in result.counter_items}}

    # -------------------------------------------------------------- validate
    def do_validate(self, snapshot_id):
        topo = self.topo
        result = self.snapshots[snapshot_id]
        preds = self.predictions()
        flows = (topo.expected_flows_routes if self.paths_present
                 else topo.expected_flows_null)
        cutoff_num, cutoff_den = self.cutoff
        scale = PPM - self.bias
        tau = self.tau
        cells = result.cell_confidence
        flow_keys = topo.flow_keys
        checked = 0
        passed = 0
        failed = []
        for flow in flows:
            keys = flow_keys[flow]
            value, num, den = cells[keys[0]]
            if num * cutoff_den < cutoff_num * den:
                continue
            expected = preds[flow] * scale
            observed = value * PPM
            difference = observed - expected
            if difference < 0:
                difference = -difference
            count = len(keys)
            checked += count
            if PPM * difference <= tau * (observed if observed > expected else expected):
                passed += count
            else:
                failed.extend(keys)
        failed.sort()
        gamma_num, gamma_den = self.gamma
        if checked:
            consistent = passed * gamma_den >= gamma_num * checked
        else:
            consistent = None
        return {'op': 'validate', 'id': snapshot_id, 'checked': checked,
                'passed': passed, 'consistent': consistent, 'failed': failed}

