    def walk(j, ben, cnt):
        rest = m - j
        limit = rest
        for pos in range(len(cap_list)):
            avail = cap_list[pos] - usage[pos] + rest - remaining[j][pos]
            if avail < limit:
                limit = avail
        if limit <= 0:
            limit = 0
        upper = (ben + suffix[j] - suffix[j + limit]) * scale - (cnt + limit)
        if upper <= state["score"]:
            return
        if j == m:
            score = ben * scale - cnt
            if score > state["score"]:
                state["score"] = score
                state["set"] = list(current)
            return
        touched = uses[j]
        feasible = True
        for pos in touched:
            if usage[pos] >= cap_list[pos]:
                feasible = False
                break
        if feasible:
            for pos in touched:
                usage[pos] += 1
            current.append(candidates[j])
            walk(j + 1, ben + benefit[candidates[j]], cnt + 1)
            current.pop()
            for pos in touched:
                usage[pos] -= 1
        walk(j + 1, ben, cnt)

    remaining = []
    for j in range(m + 1):
        row = [0] * len(cap_list)
        for pos in range(len(cap_list)):
            c = 0
            for k in range(j, m):

            for k in range(j, m):
