"""Independent slow reference implementation for testing."""
from fractions import Fraction
from itertools import product as iproduct

G = ((0, 0, 1), (1, 1, 2), (1, 1, 2))
INV = (2, 1, 0)


def canon(a, b):
    return (a, b) if a < b else (b, a)


def normalize(path, ixps):
    out = []
    for x in path:
        if x in ixps:
            continue
        if out and out[-1] == x:
            continue
        out.append(x)
    return out


def ref_peel(agg):
    paths = dict(agg)
    rounds = {}
    r = 0
    while True:
        r += 1
        allu = {}
        present = set()
        for p in paths:
            first, last = p[0], p[-1]
            for i in range(len(p) - 1):
                key = canon(p[i], p[i + 1])
                present.add(key)
                u, v = key
                if key not in allu:
                    allu[key] = [True, True]
                if not (first == u or last == u):
                    allu[key][0] = False
                if not (first == v or last == v):
                    allu[key][1] = False
        marked = set()
        for k in present:
            if allu[k][0] or allu[k][1]:
                marked.add(k)
        if not marked:
            break
        for k in marked:
            rounds[k] = r
        newpaths = {}
        for p, c in paths.items():
            fl = canon(p[0], p[1])
            ll = canon(p[-2], p[-1])
            s = 1 if fl in marked else 0
            e = len(p) - 1 if ll in marked else len(p)
            q = p[s:e]
            if len(q) >= 2:
                newpaths[q] = newpaths.get(q, 0) + c
        paths = newpaths
