#!/usr/bin/env python3
"""Offline BGP relationship inference and route-leak scoring service."""

import sys
import json
import re
from fractions import Fraction
from itertools import product
from math import gcd


class Invalid(Exception):
    pass


def bad(*args, **kwargs):
    raise Invalid()


AS_RE = re.compile(r"[A-Za-z0-9_.-]{1,64}\Z")
TOP_KEYS = {"version", "ixps", "rib", "priors", "declared", "order", "queries"}
MAX_INPUT = 4194304

# c2p, p2p, p2c are represented by 0, 1, 2.
# g[L][R]
G = (
    (0, 0, 1),
    (1, 1, 2),
    (1, 1, 2),
)


def is_int(x):
    return type(x) is int


def asn_ok(x):
    return type(x) is int and 1 <= x <= 4294967295


def canonical(a, b):
    return (a, b) if a < b else (b, a)


def check_asn(x):
    if not asn_ok(x):
        raise Invalid()


def check_path(p):
    if type(p) is not list or len(p) > 64:
        raise Invalid()
    for x in p:
        check_asn(x)


def check_link(raw):
    if type(raw) is not list or len(raw) != 2:
        raise Invalid()
    u, v = raw
    check_asn(u)
    check_asn(v)
    if u == v:
        raise Invalid()
    return u, v


def check_threshold(raw):
    if type(raw) is not list or len(raw) != 2:
        raise Invalid()
    a, b = raw
    if not is_int(a) or not is_int(b):
        raise Invalid()
    if b < 1 or a < 0 or a > b or b > 1000000:
        raise Invalid()
    return a, b


def normalize_path(path, ixps):
    # Remove IXPs first, then collapse maximal adjacent duplicate runs in place.
    out = []
    for x in path:
        if x in ixps:
            continue
        if not out or out[-1] != x:
            out.append(x)
    return tuple(out)


def parse_request():
    raw = sys.stdin.buffer.read(MAX_INPUT + 1)
    if len(raw) > MAX_INPUT:
        raise Invalid()
    try:
        text = raw.decode("utf-8")
        obj = json.loads(
            text,
            object_pairs_hook=no_duplicate_object,
            parse_float=bad,
            parse_constant=bad,
        )
    except Invalid:
        raise
    except Exception:
        raise Invalid()
    return obj


def no_duplicate_object(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Invalid()
        d[k] = v
    return d


def validate(data):
    if type(data) is not dict:
        raise Invalid()
    if set(data.keys()) != TOP_KEYS:
        raise Invalid()
    if not is_int(data["version"]) or data["version"] != 1:
