            if fid not in enabled:
                mode = 'ip'
                reason = 'disabled'
            else:
                tmpl = f['template']
                if any(header[i] != tmpl[i] for i in f['k_idx']):
                    mode = 'ip'
                    reason = 'mismatch'
                elif header[f['q_idx']] > 7:
                    mode = 'ip'
                    reason = 'qos'
                else:
                    mode = 'mpls'
                    reason = 'compressed'

            ttl = header[f['t_idx']]
            n = len(f['path'])
            wire = []
            byte_hops = 0
            delivered = None

            if ttl != 0:
                cur = ttl
                if mode == 'mpls':
                    residue = bytes(header[i] for i in f['d_idx'])
                    q = header[f['q_idx']]
                    labels = f['labels']
