        "path": nodes,
        "pidx": dict((n, i) for i, n in enumerate(nodes)),

        "pidx": dict((n, i) for i, n in enumerate(nodes)),
        "N": N,
        "h": N - 1,
        "H": H,
        "tmpl": tmpl,
        "base": base,
        "kpos": kpos,
        "dpos": dpos,
        "zpos": zpos,
        "q": qoff,
        "t": toff,
        "labels": None,
    }
