                evs.append((op, fid))
            elif op == "reset":
                _keys(ev, frozenset(("op",)))
                evs.append(("reset",))
            else:
                raise Bad()
        return {"mode": "replay", "caps": caps, "flows": F, "events": evs}
    warmup = req["warmup"]
    if not _isint(warmup) or not (0 <= warmup <= 1000000000):
        raise Bad()
    pinned = req["pinned"]
    if type(pinned) is not list:
        raise Bad()
    pin = []
    for p in pinned:
        _id(p)
        if p not in F:
            raise Bad()
        if p in pin:
            raise Bad()
        pin.append(p)
    offers = req["offers"]
    if type(offers) is not dict or set(offers) != set(F):
        raise Bad()
    hdr_bytes = 0
    runs = {}
    for fid, lst in offers.items():
        if type(lst) is not list or not (0 <= len(lst) <= 256):
            raise Bad()
        H = F[fid]["H"]
        seq = []
        tot = 0
        for r in lst:
