class RepairCache:
    __slots__ = ("slots", "entries")

    def __init__(self, slots):
        self.slots = slots
        self.entries = OrderedDict()

    def lookup(self, key):
        if self.slots <= 0:
            return None
        payload = self.entries.get(key)
        if payload is None:
            return None
